import { Injectable } from "@angular/core";
import { MatPaginatorIntl } from "@angular/material/paginator";

@Injectable()
export class MatPaginatorService extends MatPaginatorIntl {
  itemsPerPageLabel = 'Itens por página:';
  nextPageLabel     = 'Página seguinte';
  previousPageLabel = 'Página anterior';
  firstPageLabel    = 'Primeira página';
  lastPageLabel     = 'Última página';

  getRangeLabel = function (page, pageSize, length) {
    if (length === 0 || pageSize === 0) {
      return '0 de ' + length;
    }
    length = Math.max(length, 0);
    const startIndex = page * pageSize;
    // If the start index exceeds the list length, do not try and fix the end index to the end.
    const endIndex = startIndex < length ?
      Math.min(startIndex + pageSize, length) :
      startIndex + pageSize;
    return startIndex + 1 + ' - ' + endIndex + ' de ' + length;
  };
}

import { Injectable } from '@angular/core';
import { IndividualConfig, ToastrService } from 'ngx-toastr';
import { Mensagem } from './mensagem.types';
import { NotificationToast } from 'layout/common/notification-toast/notification.toast.component';

@Injectable({
    providedIn: 'root',
})
export class MensagemService {
    constructor(private _toastrService: ToastrService) {}

    default(conteudo: string, desabilitarTimeOut?: boolean) {
        if (conteudo) {
            return this._toastrService.show(
                conteudo,
                '',
                MensagemService.obterConfiguracoesToastr(desabilitarTimeOut)
            ).toastId;
        }
    }

    info(conteudo: string, desabilitarTimeOut?: boolean) {
        if (conteudo) {
            return this._toastrService.info(
                conteudo,
                'Informação',
                MensagemService.obterConfiguracoesToastr(desabilitarTimeOut)
            ).toastId;
        }
    }

    processamento(conteudo: string, desabilitarTimeOut?: boolean) {
        if (conteudo) {
            return this._toastrService.info(
                conteudo,
                'Em Processamento!',
                MensagemService.obterConfiguracoesToastrParaProcessamento(
                    desabilitarTimeOut
                )
            ).toastId;
        }
    }

    sucesso(conteudo: string, desabilitarTimeOut?: boolean) {
        if (conteudo) {
            return this._toastrService.success(
                conteudo,
                'Sucesso',
                MensagemService.obterConfiguracoesToastr(desabilitarTimeOut)
            ).toastId;
        }
    }

    alerta(conteudo: string, desabilitarTimeOut?: boolean) {
        if (conteudo) {
            return this._toastrService.warning(
                conteudo,
                'Atenção',
                MensagemService.obterConfiguracoesToastr(desabilitarTimeOut)
            ).toastId;
        }
    }

    erro(conteudo: string, desabilitarTimeOut?: boolean) {
        if (conteudo) {
            return this._toastrService.error(
                conteudo,
                'Erro',
                MensagemService.obterConfiguracoesToastr(desabilitarTimeOut)
            ).toastId;
        }
    }

    fluxo(conteudo: string, desabilitarTimeOut?: boolean) {
        if (conteudo) {
            return this._toastrService.error(
                conteudo,
                'Ação não realizada',
                MensagemService.obterConfiguracoesToastr(desabilitarTimeOut)
            ).toastId;
        }
    }

    tipo(tipo: string, conteudo: string, desabilitarTimeOut?: boolean): number {
        let idMensagem: number;
        if (conteudo) {
            if (tipo == 'INFO') {
                idMensagem = this.sucesso(conteudo, desabilitarTimeOut);
            }
            if (tipo == 'WARN') {
                idMensagem = this.alerta(conteudo, desabilitarTimeOut);
            }
            if (tipo == 'ERROR') {
                idMensagem = this.erro(conteudo, desabilitarTimeOut);
            }
            if (tipo == 'FLUXO') {
                idMensagem = this.fluxo(conteudo, desabilitarTimeOut);
            }
        }
        return idMensagem;
    }

    exibirMensagens(listaMensagem: Mensagem[]): void {
        if (listaMensagem) {
            listaMensagem.forEach((mensagem: Mensagem) =>
                this.tipo(mensagem.tipoMessage, mensagem.message)
            );
        }
    }

    limparMensagens(listaIdMensagem: number[]) {
        listaIdMensagem.forEach((idMensagem) => {
            this._toastrService.clear(idMensagem);
        });
    }

    openNotificationToast(conteudo: string) {
        if (conteudo) {
            return this._toastrService.show(
                conteudo,
                'Nova Notificação',
                MensagemService.obterConfiguracoesNotificationToastr()
            ).toastId;
        }
    }

    private static obterConfiguracoesNotificationToastr(): Partial<IndividualConfig> {
        return {
            closeButton: true,
            timeOut: 50000,
            enableHtml: true,
            progressBar: true,
            progressAnimation: 'decreasing',
            disableTimeOut: false,
            positionClass: 'toast-top-right',
            toastComponent: NotificationToast,
        };
    }

    private static obterConfiguracoesToastr(
        desabilitarTimeOut?: boolean
    ): Partial<IndividualConfig> {
        return {
            closeButton: true,
            timeOut: 10000,
            enableHtml: true,
            progressBar: true,
            progressAnimation: 'decreasing',
            disableTimeOut: desabilitarTimeOut,
            positionClass: desabilitarTimeOut
                ? 'toast-bottom-right'
                : 'toast-top-right',
        };
    }

    private static obterConfiguracoesToastrParaProcessamento(
        desabilitarTimeOut?: boolean
    ): Partial<IndividualConfig> {
        return {
            closeButton: false,
            timeOut: 15000,
            enableHtml: true,
            progressBar: true,
            progressAnimation: 'decreasing',
            disableTimeOut: desabilitarTimeOut,
            positionClass: desabilitarTimeOut
                ? 'toast-bottom-right'
                : 'toast-top-right',
        };
    }
}

import { Injectable } from '@angular/core';
import { assign, cloneDeep } from 'lodash-es';
import { FuseMockApiService, FuseMockApiUtils } from '@fuse/lib/mock-api';
import { messages as messagesData } from 'core/mock-api/common/messages/data';

@Injectable({
    providedIn: 'root',
})
export class MessagesMockApi {
    private _messages: any = messagesData;

    /**
     * Constructor
     */
    constructor(private _fuseMockApiService: FuseMockApiService) {
        // Register Mock API handlers
        this.registerHandlers();
    }

    // -----------------------------------------------------------------------------------------------------
    // @ Public methods
    // -----------------------------------------------------------------------------------------------------

    /**
     * Register Mock API handlers
     */
    registerHandlers(): void {
        // -----------------------------------------------------------------------------------------------------
        // @ Messages - GET
        // -----------------------------------------------------------------------------------------------------
        this._fuseMockApiService
            .onGet('api/common/messages')
            .reply(() => [200, cloneDeep(this._messages)]);

        // -----------------------------------------------------------------------------------------------------
        // @ Messages - POST
        // -----------------------------------------------------------------------------------------------------
        this._fuseMockApiService
            .onPost('api/common/messages')
            .reply(({ request }) => {
                // Get the message
                const newMessage = cloneDeep(request.body.message);

                // Generate a new GUID
                newMessage.id = FuseMockApiUtils.guid();

                // Unshift the new message
                this._messages.unshift(newMessage);

                // Return the response
                return [200, newMessage];
            });

        // -----------------------------------------------------------------------------------------------------
        // @ Messages - PATCH
        // -----------------------------------------------------------------------------------------------------
        this._fuseMockApiService
            .onPatch('api/common/messages')
            .reply(({ request }) => {
                // Get the id and message
                const id = request.body.id;
                const message = cloneDeep(request.body.message);

                // Prepare the updated message
                let updatedMessage = null;

                // Find the message and update it
                this._messages.forEach(
                    (item: any, index: number, messages: any[]) => {
                        if (item.id === id) {
                            // Update the message
                            messages[index] = assign(
                                {},
                                messages[index],
                                message
                            );

                            // Store the updated message
                            updatedMessage = messages[index];
                        }
                    }
                );

                // Return the response
                return [200, updatedMessage];
            });

        // -----------------------------------------------------------------------------------------------------
        // @ Messages - DELETE
        // -----------------------------------------------------------------------------------------------------
        this._fuseMockApiService
            .onDelete('api/common/messages')
            .reply(({ request }) => {
                // Get the id
                const id = request.params.get('id');

                // Prepare the deleted message
                let deletedMessage = null;

                // Find the message
                const index = this._messages.findIndex(
                    (item: any) => item.id === id
                );

                // Store the deleted message
                deletedMessage = cloneDeep(this._messages[index]);

                // Delete the message
                this._messages.splice(index, 1);

                // Return the response
                return [200, deletedMessage];
            });

        // -----------------------------------------------------------------------------------------------------
        // @ Mark all as read - GET
        // -----------------------------------------------------------------------------------------------------
        this._fuseMockApiService
            .onGet('api/common/messages/mark-all-as-read')
            .reply(() => {
                // Go through all messages
                this._messages.forEach(
                    (item: any, index: number, messages: any[]) => {
                        // Mark it as read
                        messages[index].read = true;
                        messages[index].seen = true;
                    }
                );

                // Return the response
                return [200, true];
            });

        // -----------------------------------------------------------------------------------------------------
        // @ Toggle read status - POST
        // -----------------------------------------------------------------------------------------------------
        this._fuseMockApiService
            .onPost('api/common/messages/toggle-read-status')
            .reply(({ request }) => {
                // Get the message
                const message = cloneDeep(request.body.message);

                // Prepare the updated message
                let updatedMessage = null;

                // Find the message and update it
                this._messages.forEach(
                    (item: any, index: number, messages: any[]) => {
                        if (item.id === message.id) {
                            // Update the message
                            messages[index].read = message.read;

                            // Store the updated message
                            updatedMessage = messages[index];
                        }
                    }
                );

                // Return the response
                return [200, updatedMessage];
            });
    }
}

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { map, Observable, ReplaySubject, switchMap, take, tap } from 'rxjs';
import { Message } from 'layout/common/messages/messages.types';

@Injectable({
    providedIn: 'root',
})
export class MessagesService {
    private _messages: ReplaySubject<Message[]> = new ReplaySubject<Message[]>(
        1
    );

    /**
     * Constructor
     */
    constructor(private _httpClient: HttpClient) {}

    // -----------------------------------------------------------------------------------------------------
    // @ Accessors
    // -----------------------------------------------------------------------------------------------------

    /**
     * Getter for messages
     */
    get messages$(): Observable<Message[]> {
        return this._messages.asObservable();
    }

    // -----------------------------------------------------------------------------------------------------
    // @ Public methods
    // -----------------------------------------------------------------------------------------------------

    /**
     * Get all messages
     */
    getAll(): Observable<Message[]> {
        return this._httpClient.get<Message[]>('api/common/messages').pipe(
            tap((messages) => {
                this._messages.next(messages);
            })
        );
    }

    /**
     * Create a message
     *
     * @param message
     */
    create(message: Message): Observable<Message> {
        return this.messages$.pipe(
            take(1),
            switchMap((messages) =>
                this._httpClient
                    .post<Message>('api/common/messages', { message })
                    .pipe(
                        map((newMessage) => {
                            // Update the messages with the new message
                            this._messages.next([...messages, newMessage]);

                            // Return the new message from observable
                            return newMessage;
                        })
                    )
            )
        );
    }

    /**
     * Update the message
     *
     * @param id
     * @param message
     */
    update(id: string, message: Message): Observable<Message> {
        return this.messages$.pipe(
            take(1),
            switchMap((messages) =>
                this._httpClient
                    .patch<Message>('api/common/messages', {
                        id,
                        message,
                    })
                    .pipe(
                        map((updatedMessage: Message) => {
                            // Find the index of the updated message
                            const index = messages.findIndex(
                                (item) => item.id === id
                            );

                            // Update the message
                            messages[index] = updatedMessage;

                            // Update the messages
                            this._messages.next(messages);

                            // Return the updated message
                            return updatedMessage;
                        })
                    )
            )
        );
    }

    /**
     * Delete the message
     *
     * @param id
     */
    delete(id: string): Observable<boolean> {
        return this.messages$.pipe(
            take(1),
            switchMap((messages) =>
                this._httpClient
                    .delete<boolean>('api/common/messages', { params: { id } })
                    .pipe(
                        map((isDeleted: boolean) => {
                            // Find the index of the deleted message
                            const index = messages.findIndex(
                                (item) => item.id === id
                            );

                            // Delete the message
                            messages.splice(index, 1);

                            // Update the messages
                            this._messages.next(messages);

                            // Return the deleted status
                            return isDeleted;
                        })
                    )
            )
        );
    }

    /**
     * Mark all messages as read
     */
    markAllAsRead(): Observable<boolean> {
        return this.messages$.pipe(
            take(1),
            switchMap((messages) =>
                this._httpClient
                    .get<boolean>('api/common/messages/mark-all-as-read')
                    .pipe(
                        map((isUpdated: boolean) => {
                            // Go through all messages and set them as read
                            messages.forEach((message, index) => {
                                messages[index].read = true;
                            });

                            // Update the messages
                            this._messages.next(messages);

                            // Return the updated status
                            return isUpdated;
                        })
                    )
            )
        );
    }
}

