    public type: 'REGULAR' | 'INDIVIDUAL' | 'ESTAGIARIO' | 'RESIDENTE';
    public observation: string = '';
    public parcel_number: number = 0;
    public totalDays: number = 0;

    public usufructs_in: {
        start_date: Date;
        end_date: Date;
        days?: number;
        parcel_number?: number;
        sale_usufruct?: number;
    }[] = [];

    public substitutes: {
        start_date: Date;
        end_date: Date;
        substitute: number;
        exercise: number;
    }[] = [];

