    set dataInicio(data: Date | null) {
        this.dataInicioSource.next(data);
    }

    get dataFim(): Date | null {
        return this.dataFimSource.value;
    }

    set dataFim(data: Date | null) {
        this.dataFimSource.next(data);
    }

    get telaAprovador(): boolean | null {
