        @Inject(MAT_DIALOG_DATA) 
        protected data: CienciaCancelamentoComponentData,
        protected dialogRef: MatDialogRef<CienciaCancelamentoComponentData>,
        protected snackBar: MatSnackBar,
    ) {}

    async ngOnInit() {
        await this.carregarBeneficiarios();
