    @Output() onSelect: EventEmitter<any> = new EventEmitter<any>();

    private subscription: Subscription;
    private obterOpcoesSubject = new Subject();

    private opcoesSubject = new BehaviorSubject<
        { titulo: string; valor: string }[]
    >([]);
    private loadingSubject = new BehaviorSubject<boolean>(false);

    public opcoes$ = this.opcoesSubject.asObservable();
    public loading$ = this.loadingSubject.asObservable();

    public palavra_chave: string;
    public selecionado: any = undefined;
    public ativarSelecao = false;

    constructor() {}

    ngOnInit() {
        this.ativarSelecao = true;
    }

    ngOnDestroy() {
        this.subscription?.unsubscribe();
    }

    ngOnChanges(changes) {
        this.obterOpcoes();
    }

    ngAfterViewInit() {
        this.subscription = this.obterOpcoesSubject
            .pipe(debounceTime(1000))
            .subscribe((e) => {
                this.obterOpcoes();
            });
    }

    private async obterTitulo(linha: any) {
        const obterTitulo = this.configuracao.obterTitulo;

        if (!obterTitulo)
            return linha?.nome || linha?.titulo || linha?.descricao;

        if (ehString(obterTitulo)) return linha[obterTitulo as string];

        if (ehFuncao(obterTitulo))
            return await (obterTitulo as Function)(linha);

        return 'OPS....';
    }

    private async obterValor(linha: any) {
        const obterValor = this.configuracao.obterValor;

        if (!obterValor) return linha?.id || linha?.pk;

        if (ehString(obterValor)) return linha[obterValor as string];

        if (ehFuncao(obterValor)) return await (obterValor as Function)(linha);
    }

    private async obterFiltros(): Promise<((payload: any) => any[]) | Object> {
        if (typeof this.configuracao.obterFiltros === 'function') {
            return this.configuracao.obterFiltros({
                palavra_chave: this.palavra_chave,
            });
        } else {
            return { palavra_chave: this.palavra_chave };
        }
    }

    async mapear(linhas: any[]) {
        return Promise.all(
            linhas.map(async (linha) => {
                return {
                    titulo: await this.obterTitulo(linha),
                    valor: await this.obterValor(linha),
                };
            })
        );
    }

    private async obterOpcoes() {
        const filtros = await this.obterFiltros();

        const { obterOpcoes } = this.configuracao;
        let opcoes = [];
        if (obterOpcoes) {
            const response = await obterOpcoes(filtros);
            if (response && response.results) {
                opcoes = await this.mapear(response.results);
            } else {
                opcoes = [];
            }
        }

        this.opcoesSubject.next(opcoes);
    }

    public aplicarFiltros() {
        this.obterOpcoesSubject.next({});
    }

    public limparSelecao(): void {
        this.selecionado = undefined;
        this.onChange(undefined);
        this.aplicarFiltros();
    }

    public resetarSelecao(): void {
        this.selecionado = undefined;
        this.onChange(undefined);
        this.palavra_chave = '';
        this.aplicarFiltros();
    }

    public selecionar(opcao: any) {
        this.selecionado = opcao;
        if (this.mode == 'OBJECT') this.onChange(opcao);
        else this.onChange(opcao?.valor);

        this.onSelect.emit(opcao);
    }

    displayFn(opcao: any): string {
        // if (this.selecionado?.titulo) return this.selecionado?.titulo;
        // if (this.valor) return this.valor.toString();
        // if (opcao?.titulo) return opcao?.titulo;
        // return opcao;

        if (!opcao) return '';
        return opcao?.titulo?.replace(/<[^>]*>/g, '');
    }

    get multiple() {
        if (this.valor instanceof Array) return true;
        return false;
    }

    /** */
    mode: 'OBJECT' | 'PRIMITIVE';
    valor: string | number | boolean | object = '';
    onChange: any = () => {};
    onTouched: any = () => {};

    writeValue(value: string | any): void {
        this.mode ||= value === null ? 'PRIMITIVE' : undefined;
        this.mode ||= typeof value == 'object' ? 'OBJECT' : 'PRIMITIVE';
        if (this.mode == 'OBJECT') {
            this.selecionar({
                titulo: value?.titulo,
                valor: value?.valor,
            });
        } else {
            this.selecionar({
                titulo: value,
                valor: value,
            });
        }
        this.palavra_chave = value || '';
        this.valor = value;
        this.onChange(this.valor);
        this.obterOpcoesSubject.next({});
    }

    registerOnChange(fn: any): void {
        this.onChange = fn;
    }
    registerOnTouched(fn: any): void {
        this.onTouched = fn;
    }

    setDisabledState?(isDisabled: boolean): void {
        setTimeout(() => {
            this.disabled = isDisabled;
        }, 10);
    }
}

import { ChangeDetectorRef, Component, ElementRef, Input, OnInit, ViewChild, forwardRef } from '@angular/core';
import { FormControl, FormGroup, NG_VALUE_ACCESSOR, ControlValueAccessor } from '@angular/forms';
import { MatSelect } from '@angular/material/select';

export class MpmtSelecaoFormComponentConfiguracao {
    obterTitulo?: string;
    obterValor?: string;
    obterFiltros?: ((payload: any) => Promise<Object>) | Object;
    obterOpcoes?: (payload: any) => Promise<{ results: any[] }>;
}

interface Opcao {
    valor: number | string;
    titulo: string;
}

@Component({
    selector: 'mpmt-selecao-form',
    templateUrl: './mpmt-selecao-form.component.html',
    styleUrls: ['./mpmt-selecao-form.component.scss'],
    providers: [
        {
            provide: NG_VALUE_ACCESSOR,
            useExisting: forwardRef(() => MpmtSelecaoFormComponent),
            multi: true,
        },
    ],
})
export class MpmtSelecaoFormComponent implements OnInit, ControlValueAccessor {
    form: FormGroup;
    opcoes: Opcao[] = []

    constructor(private cdr: ChangeDetectorRef) {}

    @Input() titulo?: string = '';
    @Input() titulo_class?: string = '';
    @Input() placeholder?: string = 'Pesquisar';
    @Input() configuracao?: MpmtSelecaoFormComponentConfiguracao;
    @Input() form_control?: FormControl;
    @Input() isReadOnly?: boolean = false;

    palavra_chave = "";
    tituloSelecionado: string = "";

    @ViewChild('selecaoOpcoes') selecaoOpcoes: MatSelect;
    @ViewChild('pesquisarInput', { static: false }) pesquisarInput: ElementRef;

    async ngOnInit() {
        this.form = new FormGroup({
            form_control: this.form_control
        });

        if (this.isReadOnly) {
            this.form.get('form_control').disable();
        } else {
            this.form.get('form_control').enable();
        }

        await this.obterOpcoes().then(() => {
            this.setarTituloInicial();
        });
    }

    openSelect() {
        this.selecaoOpcoes.open();
    }

    private async obterTitulo(linha: any) {
        const obterTitulo = this.configuracao.obterTitulo;

        if (!obterTitulo)
            return linha?.nome || linha?.titulo || linha?.descricao;

        return linha[obterTitulo as string];

    }

    private async obterValor(linha: any) {
        const obterValor = this.configuracao.obterValor;

        if (!obterValor) return linha?.id || linha?.pk;

        return linha[obterValor];

    }

    private async obterFiltros(): Promise<((payload: any) => any[]) | Object> {
        if (typeof this.configuracao.obterFiltros === 'function') {
            return this.configuracao.obterFiltros({
                palavra_chave: this.palavra_chave,
            });
        } else {
            return {};
        }
    }

    async mapear(linhas: any[]) {
        return Promise.all(
            linhas.map(async (linha) => {
                return {
                    titulo: await this.obterTitulo(linha),
                    valor: await this.obterValor(linha),
                };
            })
        );
    }

    private async obterOpcoes() {
        const filtros = await this.obterFiltros();

        const { obterOpcoes } = this.configuracao;

        if (obterOpcoes) {
            const response = await obterOpcoes(filtros);
            if (response && response.results) {
                this.opcoes = await this.mapear(response.results);
            } else {
                this.opcoes = [];
            }
        }
    }

    public aplicarFiltros(event: KeyboardEvent) {
        const inputElement = event.target as HTMLInputElement;
        this.palavra_chave = inputElement.value;
        this.obterOpcoes();
    }

    public async limparSelecao() {
        this.onChange(null);
        this.palavra_chave = '';
        await this.obterOpcoes();
        await this.setarTituloInicial();
    }

    public setarSelecao(valor: number | string) {
        this.onChange(valor);
        this.form.get('form_control').setValue(valor);
        this.palavra_chave = '';
    }

    public onSelectionChange(event: any) {
        const opcaoSelecionada = this.opcoes.find(opcao => opcao.valor === event.value);
        if (opcaoSelecionada) {
            this.tituloSelecionado = opcaoSelecionada.titulo; // Atualize o input com o título selecionado
        }
        this.pesquisarInput.nativeElement.value = this.tituloSelecionado; // Mostra o título no input
        this.onChange(event.value);
        this.form.get('form_control').setValue(event.value);
    }

    private async setarTituloInicial() {
        const valorSelecionado = this.form.get('form_control').value;
        if (valorSelecionado) {
          const opcaoSelecionada = this.opcoes.find(opcao => opcao.valor === valorSelecionado);
          if (opcaoSelecionada) {
            this.tituloSelecionado = opcaoSelecionada.titulo;
            this.pesquisarInput.nativeElement.value = this.tituloSelecionado; 

            this.cdr.detectChanges();
          }
        }
    }

    // ControlValueAccessor 
    value: string | number;
    onChange = (value: string | number) => { };
    onTouched = () => { };

    onInput(event: Event) {
        const input = event.target as HTMLInputElement;
        this.value = input.value;
        this.onChange(this.value);
    }

    writeValue(value: string | number): void {
        this.value = value;
    }

    registerOnChange(fn: (value: string | number) => void): void {
        this.onChange = fn;
    }

    registerOnTouched(fn: () => void): void {
        this.onTouched = fn;
    }

    setDisabledState?(isDisabled: boolean): void {
        if (isDisabled) {
            this.form.get('form_control').disable();
        } else {
            this.form.get('form_control').enable();
        }
    }
}

import { Component, HostListener, Inject, Input, OnInit } from '@angular/core';
import { MAT_DIALOG_DATA, MatDialog } from '@angular/material/dialog';
import {
    DomSanitizer,
    SafeResourceUrl,
    SafeUrl,
} from '@angular/platform-browser';

export class MpPdfPreviewComponentData {
    link: string;
    close: () => void;
}

@Component({
    selector: 'mp-pdf-preview',
    templateUrl: './mp-pdf-preview.component.html',
})
export class MpPdfPreviewComponent {
    isLoading: boolean = true;
    srclink;

    constructor(
        sanitizer: DomSanitizer,
        public dialog: MatDialog,
        @Inject(MAT_DIALOG_DATA)
        public payload: MpPdfPreviewComponentData
    ) {
        if (payload.link) {
            this.srclink = sanitizer.bypassSecurityTrustResourceUrl(
                payload.link
            );
        }
    }

    isFirefox(): boolean {
        const userAgent = window.navigator.userAgent.toLowerCase();
        return userAgent.indexOf('firefox') > -1;
    }

    public open(link: string): void {
        const dialogRef = this.dialog.open(MpPdfPreviewComponent, {
            width: '90%',
            height: '90%',
            data: <MpPdfPreviewComponentData>{
                link,
                close: () => {
                    dialogRef.close();
                },
            },
        });
    }

    goClose() {
        if (this.payload?.close) this.payload?.close();
        else this.dialog.closeAll();
    }

    getData() {
        //Adaptação feita pois estava ocorrendo um problema ao tentar baixar no firefox usando o mesmo srclink novamente.
        if (this.isFirefox()) {
            return null;
        }

        return this.srclink;
    }
}

