    @Output() readonly irNovo: EventEmitter<null> = new EventEmitter<null>();
    @Output() readonly irEditar: EventEmitter<any> = new EventEmitter<any>();

    isLoading: boolean = true;

    constructor(
        @Inject(MAT_DIALOG_DATA)
