    isRequestTipoCancelamentoTeletrabalho,
    isRequestTipoSolicitacaoAuxilioCrecheIr,
    isRequestTipoSolicitacaoCreditoFolga,
    isRequestTypeAbsence,
    isRequestTypeCancel,
    isRequestTypeExecicioCumulativo,
