    lista2Retorno:any[] = []

    nome:string = null
    id:number = null;

    form: FormGroup;

    servidor: any = null;

    situacao = true;
    situacoes = [{value: true, label: "Ativo"}, {value: false, label: "Inativo"}]

    selecaoCatFuncional: MpmtSelecaoComponentConfiguracao = {
        obterOpcoes: apiRhCategoriaFuncional,
        obterValor: 'cod',
    };

    categoriaFuncional: any;

    filtro: {
        palavra_chave: string,
        page: number,
        per_page: number,
        situacao: boolean,
        tipo_posse: string[]
    }

