import { Component, Inject, ViewChild } from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { DateAdapter } from '@angular/material/core';
import {
    MAT_DIALOG_DATA,
    MatDialog,
    MatDialogRef,
} from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';
import { apiAnotacoesPessoaisCriar } from 'api/anotacoes-pessoais/api-anotacoes-pessoais-criar.service';
import { apiAnotacoesPessoaisTiposDocumentos } from 'api/anotacoes-pessoais/api-anotacoes-pessoais-tipos-documentos.service';
import { apiAnotacaoPessoalTiposAnotacao } from 'api/anotacoes-pessoais/api-anotacoes-pessoal-minhas-anotacoes.service';
import { apiRhPublicacoes } from 'api/rh/api-rh-publicacoes.service';
import { apiRhSevidoresService } from 'api/rh/api-rh-servidores.service';
import { MpmtFormularioComponent } from 'components/mpmt-formulario/mpmt-formulario.component';
import {
    MpmtSelecaoComponent,
    MpmtSelecaoComponentConfiguracao,
} from 'components/mpmt-selecao/mpmt-selecao.component';
import moment from 'moment';
import { ModalPublicacoesComponent } from '../publicacoes/modal-publicacoes/modal-publicacoes.component';

class AnotacoesPessoaisNovoComponentData {
    onClose?: Function;
}

@Component({
    selector: 'anotacoes-pessoais-novo',
    templateUrl: 'anotacoes-pessoais-novo.component.html',
    styles: [
        `
            :host ::ng-deep .ck-editor__editable_inline {
                min-height: 180px;
            }
        `,
    ],
})
export class AnotacoesPessoaisNovoComponent extends MpmtFormularioComponent<AnotacoesPessoaisNovoComponentData> {
    @ViewChild('documentoTipoSelecao')
    documentoTipoSelecao: MpmtSelecaoComponent;

    protected formulario = new FormGroup({
        data_publicacao: new FormControl<string | Date>(null, []),
        data_expedicao_publicacao: new FormControl<string | Date>(null, []),
        documento_data: new FormControl<string>(''),
        documento_numero: new FormControl<string>('', [Validators.required]),
        servidor: new FormControl<number>(null, [Validators.required]),
        documento_ano: new FormControl<string | number>(null, [
            Validators.required,
        ]),
        documento_tipo: new FormControl<string | number | null>(null, [
            Validators.required,
        ]),
        tipo: new FormControl<number | null>(null, [Validators.required]),
        tipo_anotacao_id: new FormControl<number>(null),
        gedoc_numero: new FormControl<string>(''),
        matricula: new FormControl<string>(''),
        servidor_nome: new FormControl<string>(''),
        tipo_display: new FormControl<string>(''),
        publicacao: new FormControl<{
            valor: number;
            titulo: string;
        }>({ valor: null, titulo: null }),
        data_efeito_inicio: new FormControl<string>(''),
        data_efeito_fim: new FormControl<string>(''),
        documento_tipo_display: new FormControl<string>(''),
        texto: new FormControl<string>(''),
        textoAtualizado: new FormControl<string>('', [Validators.required]),
        publicacao_display: new FormControl<string>('', []),
    });

    constructor(
        @Inject(MAT_DIALOG_DATA)
        protected data: AnotacoesPessoaisNovoComponentData,
        protected dialogRef: MatDialogRef<AnotacoesPessoaisNovoComponentData>,
        protected snackBar: MatSnackBar,
        protected dateAdapter: DateAdapter<Date>,
        public dialog: MatDialog
    ) {
        super(data, snackBar, dialogRef);

        this.dateAdapter.setLocale('pt-BR');
    }

    protected irNovoPublicacao() {
        this.dialog.open(ModalPublicacoesComponent, {
            data: {
                onClose: (publicacao) => {
                    this.formulario.patchValue({
                        publicacao: {
                            valor: publicacao.id,
                            titulo: publicacao.unicode,
                        },
                        publicacao_display: publicacao.cache_unicode,
                        data_publicacao: this.formatarData(
                            publicacao.data_publicacao
                        ),
                        data_expedicao_publicacao: this.formatarData(
                            publicacao.data_expedicao
                        ),
                    });
                },
            },
            width: '80%',
            height: '90%',
        });
    }

    protected irEditarPublicacao() {
        this.dialog.open(ModalPublicacoesComponent, {
            data: {
                selecionada: this.formulario.value.publicacao?.valor,
                onClose: (publicacao) => {
                    this.formulario.patchValue({
                        publicacao: {
                            valor: publicacao.id,
                            titulo: publicacao.unicode,
                        },
                        publicacao_display: publicacao.cache_unicode,
                        data_publicacao: this.formatarData(
                            publicacao.data_publicacao
                        ),
                        data_expedicao_publicacao: this.formatarData(
                            publicacao.data_expedicao
                        ),
                    });
                },
            },
            width: '80%',
            height: '90%',
        });
    }

    protected async resetarFormulario() {
        super.resetarFormulario();
    }

    protected async confirmarFormulario() {
        if (!this.formularioValido) return;

        const {
            texto,
            textoAtualizado,
            tipo,
            documento_numero,
            documento_ano,
            documento_tipo,
            documento_data,
            data_efeito_inicio,
            data_efeito_fim,
            gedoc_numero,
            servidor,
            publicacao,
        } = this.formulario.value;

        function extractDateString(date: any) {
            if (!date) return undefined;
            if (typeof date == 'string') return date;
            return date?.toDate()?.toISOString()?.substring(0, 10);
        }
        try {
            const {} = await apiAnotacoesPessoaisCriar({
                servidor,
                documento_ano,
                documento_data: extractDateString(documento_data),
                documento_numero,
                data_efeito_fim: extractDateString(data_efeito_fim),
                data_efeito_inicio: extractDateString(data_efeito_inicio),
                documento_tipo,
                gedoc_numero,
                texto: textoAtualizado,
                tipo,
                publicacao: publicacao?.valor,
            });

            this.resetarFormulario();
            this.fecharFormulario();
            this.data?.onClose();
        } catch (e: any) {
            console.log(e);
            const detalheErro = e?.response?.data?.message || '';
            const texto = `Ocorreu um erro inesperado ao salvar. ${detalheErro}`;
            this.exibirMensagem('Atenção', texto);
        }
    }

    selecaoServidores: MpmtSelecaoComponentConfiguracao = {
        obterOpcoes: apiRhSevidoresService,
        obterFiltros: (payload) => {
            return {
                ...payload,
                per_page: 10,
            };
        },
        obterValor: 'pk',
        obterTitulo: 'unicode',
    };

    selecaoPublicacoes: MpmtSelecaoComponentConfiguracao = {
        obterOpcoes: apiRhPublicacoes,
        obterFiltros: (payload) => {
            return {
                ...payload,
                per_page: 10,
            };
        },
        obterValor: 'id',
        obterTitulo: 'unicode',
    };

    selecaoAnotacaoPessoalTiposAnotacao: MpmtSelecaoComponentConfiguracao = {
        obterOpcoes: apiAnotacaoPessoalTiposAnotacao,
        obterValor: 'value',
        obterTitulo: 'label',
    };

    selecaoAnotacaoPessoalTiposDocumentos: MpmtSelecaoComponentConfiguracao = {
        obterOpcoes: apiAnotacoesPessoaisTiposDocumentos,
        obterValor: 'value',
        obterTitulo: 'label',
    };

    situacoes = [
        { valor: 'ATIVO', nome: 'Ativo' },
        { valor: 'INATIVO', nome: 'Inativo' },
    ];

    updateText($event) {
        const texto = $event?.editor?.getData();
        this.formulario.patchValue({
            textoAtualizado: texto,
        });
    }

    formatarData(data) {
        return data ? moment(data).format('DD/MM/YYYY') : '';
    }
}

import { Component, Inject, OnInit, ViewChild } from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { DateAdapter } from '@angular/material/core';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';
import { apiAnotacoesPessoaisTiposDocumentos } from 'api/anotacoes-pessoais/api-anotacoes-pessoais-tipos-documentos.service';
import { apiRhOrgaoGeral } from 'api/rh/api-rh-orgao-geral.service';
import { apiRhPublicacaoEditar } from 'api/rh/api-rh-publicacao-editar.service';
import { apiRhPublicacao } from 'api/rh/api-rh-publicacao.service';
import { apiRhVeiculoPublicacao } from 'api/rh/api-rh-veiculo-publicacao.service';
import { MpmtFormularioComponent } from 'components/mpmt-formulario/mpmt-formulario.component';
import { MpmtSelecaoFormComponent, MpmtSelecaoFormComponentConfiguracao } from 'components/mpmt-selecao-form/mpmt-selecao-form.component';

class AnotacoesPessoaisEditarComponentData {
    onClose?: Function;
    id: string;
}

@Component({
    selector: 'anotacoes-pessoais-publicacao-editar',
    templateUrl: 'anotacoes-pessoais-publicacao-editar.component.html',
})
export class AnotacoesPessoaisPublicacaoEditarComponent
    extends MpmtFormularioComponent<AnotacoesPessoaisEditarComponentData>
    implements OnInit
{

    @ViewChild('selecaoTipo') selecaoTipo: MpmtSelecaoFormComponent;
    @ViewChild('selecaoOrigem') selecaoOrigem: MpmtSelecaoFormComponent;
    @ViewChild('selecaoVeiculoPublicacao') selecaoVeiculoPublicacao: MpmtSelecaoFormComponent;

    tipos: any[] = [];
    origens: any[] = [];
    veiculos: any[] = [];

    selectedTipo: string;

    protected formulario = new FormGroup({
        id: new FormControl<string>('', []),
        numero: new FormControl<string>('', []),
        tipo: new FormControl<number>(null),
        origem: new FormControl<number>(null, []),
        data_expedicao: new FormControl<string>(null, [Validators.required]),
        data_vigencia: new FormControl<string>(null, [Validators.required]),
        veiculo_publicacao: new FormControl<number>(null, []),
        numero_publicacao: new FormControl<string>(null, []),
        data_publicacao: new FormControl<Date>(null, []),
        vehicle_page: new FormControl<number>(null, []),
        interessado_nome: new FormControl<string>(null, []),
        arquivo: new FormControl<{ valor: string; titulo: string }>(null, []),
        interno: new FormControl<boolean>(false, []),
        observacao: new FormControl<string>(null, []),
        document: new FormControl<string>(null, []),
    });

    constructor(
        @Inject(MAT_DIALOG_DATA)
        protected data: AnotacoesPessoaisEditarComponentData,
        protected dialogRef: MatDialogRef<AnotacoesPessoaisEditarComponentData>,
        protected snackBar: MatSnackBar,
        protected dateAdapter: DateAdapter<Date>
    ) {
        super(data, snackBar, dialogRef);

        this.dateAdapter.setLocale('pt-BR');
    }

    ngOnInit() {
        super.ngOnInit();
        this.carregarTipos();
        this.carregarOrigens();
        this.carregarVeiculos();
    }

    protected async resetarFormulario() {
        super.resetarFormulario();

        if (!this.data.id) return;

        try {
            const response = await apiRhPublicacao({
                id: this.data.id,
            });

            const publicacao = response;

            await this.formulario.patchValue({
                ...(response as any),
                arquivo: {
                    valor: publicacao.arquivo,
                    titulo: publicacao.arquivo_display,
                },
                tipo: publicacao.tipo,
                origem: publicacao.origem,
                veiculo_publicacao: publicacao.veiculo_publicacao,
            });
        } catch (e) {
            console.error(e);
            this.exibirMensagem(
                'Atenção',
                'Erro inesperado ao carregar os valores do formulário'
            );
        }
    }

    protected async confirmarFormulario() {
        if (!this.formularioValido) return;

        const data = this.formulario.value;

        const tipo = this.selecaoTipo.form_control.value;
        const origem = this.selecaoOrigem.form_control.value;
        const veiculo_publicacao = this.selecaoVeiculoPublicacao.form_control.value;

        function extractDateString(date: any) {
            if (!date) return undefined;
            if (typeof date == 'string') return date;
            return date?.toDate()?.toISOString()?.substring(0, 10);
        }
        try {
            const response: any = await apiRhPublicacaoEditar({
                ...(data as any),
                data_vigencia: extractDateString(data.data_vigencia),
                data_expedicao: extractDateString(data.data_expedicao),
                data_publicacao: extractDateString(data.data_publicacao),
                tipo: tipo,
                origem: origem,
                veiculo_publicacao: veiculo_publicacao,
                arquivo: data.arquivo?.valor,
            });

            this.resetarFormulario();
            this.fecharFormulario();
            this.data?.onClose(response.data);
        } catch (e: any) {
            console.log(e);
            const detalheErro = e?.response?.data?.message || '';
            const texto = `Ocorreu um erro inesperado ao salvar. ${detalheErro}`;
            this.exibirMensagem('Atenção', texto);
        }
    }

    async carregarTipos() {
        try {
            const response = await this.selecoesAnotacaoPessoalTiposDocumentos.obterOpcoes({});
            if (response && response.results) {
                this.tipos = response.results.map(item => ({
                    label: item.label,
                    value: item.value,
                }));
            }
        } catch (error) {
            console.error('Erro ao carregar os tipos:', error);
        }
    }

    async carregarOrigens() {
        try {
            const response = await this.selecoesOrgaoGeral.obterOpcoes({});
            if (response && response.results) {
                this.origens = response.results.map(item => ({
                    label: item.nome,
                    value: item.id,
                }));
            }
        } catch (error) {
            console.error('Erro ao carregar as origens:', error);
        }
    }

    async carregarVeiculos() {
        try {
            const response = await this.selecoesVeiculoPublicacao.obterOpcoes({});
            if (response && response.results) {
                this.veiculos = response.results.map(item => ({
                    label: item.label,
                    value: item.value,
                }));
            }
        } catch (error) {
            console.error('Erro ao carregar os veículos:', error);
        }
    }

    selecoesOrgaoGeral: MpmtSelecaoFormComponentConfiguracao = {
        obterOpcoes: apiRhOrgaoGeral,
        obterValor: 'id',
        obterTitulo: 'nome',
    };

    selecoesVeiculoPublicacao: MpmtSelecaoFormComponentConfiguracao = {
        obterOpcoes: apiRhVeiculoPublicacao,
        obterValor: 'value',
        obterTitulo: 'label',
    };

    selecoesAnotacaoPessoalTiposDocumentos = {
        obterOpcoes: apiAnotacoesPessoaisTiposDocumentos,
        obterValor: 'value',
        obterTitulo: 'label',
    };

    situacoes = [
        { valor: 'ATIVO', nome: 'Ativo' },
        { valor: 'INATIVO', nome: 'Inativo' },
    ];
}

import { Component, Inject } from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { DateAdapter } from '@angular/material/core';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';
import { apiAnotacoesPessoaisTiposDocumentos } from 'api/anotacoes-pessoais/api-anotacoes-pessoais-tipos-documentos.service';
import { apiRhOrgaoGeral } from 'api/rh/api-rh-orgao-geral.service';
import { apiRhPublicacaoCriar } from 'api/rh/api-rh-publicacao-criar.service';
import { apiRhVeiculoPublicacao } from 'api/rh/api-rh-veiculo-publicacao.service';
import { MpmtFormularioComponent } from 'components/mpmt-formulario/mpmt-formulario.component';
import { MpmtSelecaoComponentConfiguracao } from 'components/mpmt-selecao/mpmt-selecao.component';

class AnotacoesPessoaisNovoComponentData {
    onClose?: (publicacao?: any) => void;
}

@Component({
    selector: 'anotacoes-pessoais-publicacao-novo',
    templateUrl: 'anotacoes-pessoais-publicacao-novo.component.html',
})
export class AnotacoesPessoaisPublicacaoNovoComponent extends MpmtFormularioComponent<AnotacoesPessoaisNovoComponentData> {
    tipos: any[] = [];
    origens: any[] = [];
    veiculos: any[] = [];

    protected formulario = new FormGroup({
        numero: new FormControl<string>('', []),
        tipo: new FormControl<any>(null),
        origem: new FormControl<any>(null, []),
        data_expedicao: new FormControl<string>(null, [Validators.required]),
        data_vigencia: new FormControl<string>(null, [Validators.required]),
        veiculo_publicacao: new FormControl<any>(null, []),
        numero_publicacao: new FormControl<string>(null, []),
        data_publicacao: new FormControl<Date>(null, []),
        vehicle_page: new FormControl<number>(null, []),
        interessado_nome: new FormControl<string>(null, []),
        arquivo: new FormControl<number>(null, []),
        interno: new FormControl<boolean>(false, []),
        observacao: new FormControl<string>(null, []),
        document: new FormControl<string>(null, []),
    });

    ngOnInit(): void {}

    constructor(
        @Inject(MAT_DIALOG_DATA)
        protected data: AnotacoesPessoaisNovoComponentData,
        protected dialogRef: MatDialogRef<AnotacoesPessoaisNovoComponentData>,
        protected snackBar: MatSnackBar,
        protected dateAdapter: DateAdapter<Date>
    ) {
        super(data, snackBar, dialogRef);

        this.dateAdapter.setLocale('pt-BR');
    }

    protected async resetarFormulario() {
        super.resetarFormulario();
    }

    protected async confirmarFormulario() {
        if (!this.formularioValido) return;

        const data = this.formulario.value;

        function extractDateString(date: any) {
            if (!date) return undefined;
            if (typeof date == 'string') return date;
            return date?.toDate()?.toISOString()?.substring(0, 10);
        }
        try {
            const veiculo_publicacao_value = data.veiculo_publicacao.value;
            const tipo_value = data.tipo.value;
            const origem_value = data.origem.value;
            const response: any = await apiRhPublicacaoCriar({
                ...(data as any),
                veiculo_publicacao: veiculo_publicacao_value,
                tipo: tipo_value,
                origem: origem_value,
                data_vigencia: extractDateString(data.data_vigencia),
                data_expedicao: extractDateString(data.data_expedicao),
                data_publicacao: extractDateString(data.data_publicacao),
            });

            this.resetarFormulario();
            this.fecharFormulario();
            this.data?.onClose(response.data);
        } catch (e: any) {
            console.log(e);
            const detalheErro =
                e?.response?.data?.message ||
                'Ocorreu um erro inesperado ao salvar';
            const texto = `${detalheErro}`;
            this.exibirMensagem('Atenção', texto);
        }
    }

    selecaoOrgaoGeral: MpmtSelecaoComponentConfiguracao = {
        obterOpcoes: apiRhOrgaoGeral,
        obterValor: 'id',
        obterTitulo: 'nome',
    };

    selecaoVeiculoPublicacao: MpmtSelecaoComponentConfiguracao = {
        obterOpcoes: apiRhVeiculoPublicacao,
        obterValor: 'value',
        obterTitulo: 'label',
    };

    selecaoAnotacaoPessoalTiposDocumentos: MpmtSelecaoComponentConfiguracao = {
        obterOpcoes: apiAnotacoesPessoaisTiposDocumentos,
        obterValor: 'value',
        obterTitulo: 'label',
    };

