    results: ApiRhPvfApprovalsRequestsResponseItem[];
    approvers: ApiRhPvfConfigRequestsApproversResponseItem[];
    statuses: ApiRhPvfConfigRequestsStatusResponseItem[];
    types: ApiRhPvfConfigRequestsTypeResponseItem[];
