import { Component, Inject } from '@angular/core';
import { MAT_DIALOG_DATA, MatDialog } from '@angular/material/dialog';
import { CurrentUserService } from 'core/current-user/current-user.service';
import { apiRhCurrentUserAtualizaEmailPessoalService } from 'api/rh/api-rh-current-user-atualiza-email-pessoal.service';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { apiRhCurrentUserValidaEmailPessoalService } from 'api/rh/api-rh-current-user-valida-email-pessoal.service';

@Component({
    selector: 'app-atualizacao-cadastral-email',
    templateUrl: './atualizacao-cadastral-email.component.html',
    styleUrls: ['./atualizacao-cadastral-email.component.scss'],
})
export class AtualizacaoCadastralEmailComponent {
    form = new FormGroup({
        email_pessoal: new FormControl<string | null>('', [
            Validators.required,
            Validators.email,
        ]),
    });

    formConfirmacao = new FormGroup({
        codigo_email: new FormControl<string | null>('', [
            Validators.required,
            Validators.minLength(6),
        ]),
    });

    mensagem = '';

    passo: 'CADASTRO' | 'CONFIRMACAO' | 'FINALIZACAO' = 'CADASTRO';

    alterar: boolean;

    constructor(
        public dialog: MatDialog,
        private currentUserService: CurrentUserService,
        @Inject(MAT_DIALOG_DATA) public data: any
    ) {
        this.alterar = data.alterar;

        this.currentUserService?.reload().then(() => {
            this.form.patchValue({
                email_pessoal:
                    this.currentUserService?.currentUser?.email_pessoal,
            });
        });
    }

    async abrir(alterar: boolean) {
        await this.currentUserService.load();

        const dialogRef = this.dialog.open(AtualizacaoCadastralEmailComponent, {
            disableClose: !this.emailPessoalVerificado,
            data: { alterar: alterar },
        });
    }

    get emailPessoalVerificado() {
        return this.currentUserService?.currentUser?.email_pessoal_verificado;
    }

    async abrirSeNecessario() {
        const currentUser = await this.currentUserService.load();

        if (currentUser === undefined) return;

        if (currentUser.email_pessoal_verificado) return;

        this.abrir(false);
    }

    getErrorMessage() {
        if (this.form.hasError('required')) {
            return 'Informe um e-mail válido';
        }
    }

    async confirmarCadastro() {
        try {
            this.mensagem = '';
            await apiRhCurrentUserAtualizaEmailPessoalService({
                email_pessoal: this.form.value['email_pessoal'],
            });
            this.passo = 'CONFIRMACAO';
        } catch (e) {
            this.mensagem = e?.response?.data?.message || 'E-mail inválido';
            // this.voltarCadastro();
            console.log(e);
        }
    }

    async voltarCadastro() {
        this.passo = 'CADASTRO';
    }

    async validaCodigo() {
        try {
            this.mensagem = '';
            const response = await apiRhCurrentUserValidaEmailPessoalService({
                codigo_email: this.formConfirmacao.value['codigo_email'],
            });

            this.passo = 'FINALIZACAO';
        } catch (e) {
            this.mensagem = e?.response?.data?.message || 'Código inválido';
            console.log(e);
        }
    }

    async finalizar() {
        this.goClose();
    }

    goClose() {
        this.dialog.closeAll();
    }
}

import { Component, Inject } from '@angular/core';
import {
    MatDialogRef,
    MAT_DIALOG_DATA,
    MatDialog,
} from '@angular/material/dialog';
import { CurrentUserService } from 'core/current-user/current-user.service';
import { FormControl, FormGroup, Validators } from '@angular/forms';

import {DateAdapter} from "@angular/material/core";
import {gedUpload} from "../../../../../api/ged/api-ged-upload.service";
import {MatSnackBar} from "@angular/material/snack-bar";
import {apiESocialAtualizarCertificado} from "../../../../../api/esocial/api-esocial-atualizar-certificado.service";
import {
    apiESocialBuscarCertificadoAtual
} from "../../../../../api/esocial/api-esocial-buscar-certificado-atual.service";

@Component({
    selector: 'item-tabela-criar-dialog',
    templateUrl: 'atualizar-certificado-dialog.component.html',
})
export class AtualizarCertificadoDialogComponent {

    message: string = '';
    isLoading: boolean = false;
    fileCertificadoA1 = null;
    fileIdCertificadoA1: number = null;
    fileCertificadoCAs = null;
    fileIdCertificadoCAs: number = null;

    hide: boolean = true;


    constructor(
        private dialogRef: MatDialogRef<AtualizarCertificadoDialogComponent>,
        @Inject(MAT_DIALOG_DATA) public data: any,
        protected currentUserService: CurrentUserService,
        protected dialog: MatDialog,
        protected dateAdapter: DateAdapter<Date>,
        private snackBar: MatSnackBar
    ) {
        this.dateAdapter.setLocale('pt-BR');
    }

    fechar(): void {
        this.dialogRef.close();
    }

    ngOnInit() {
        this.carregarCertificadosAtuais();
        this.formulario.controls.certificado_senha.disable();
    }


    protected formulario = new FormGroup({
        fileCertificadoA1: new FormControl<number | null>(null, []),
        certificado_id: new FormControl<number | null>(null, []),
        fileCertificadoCAs: new FormControl<number | null>(null, []),
        certificado_ca_id: new FormControl<number | null>(null, []),
        certificado_senha: new FormControl<string>('', []),
    });

    async goConfirm() {
        this.message = '';

        const { certificado_id, certificado_ca_id, certificado_senha} = this.formulario.value;

        try {
            this.isLoading = true;
            await apiESocialAtualizarCertificado({
                certificado_id, certificado_ca_id, certificado_senha
            });

            this.dialogRef.close();
        } catch (e: any) {
            this.exibirMensagem('Erro', e?.response?.data?.message);
        } finally {
            this.isLoading = false;
        }
    }

    get isValid() {
        if (this.formulario.value.certificado_ca_id == null && this.formulario.value.certificado_id == null)
            return false;

        if (this.formulario.value.certificado_id && !this.formulario.value.certificado_senha) {
            return false;
        }

        return true;
    }

    async onFileCertificadoA1Input($file) {
        this.fileCertificadoA1 = $file.target.files[0];

        if (this.fileCertificadoA1.type === "pfx" || this.fileCertificadoA1.type === "p12" ||
            this.fileCertificadoA1.type === "application/x-pkcs12") {
            const response = await gedUpload({
                file: this.fileCertificadoA1,
                fileName: this.fileCertificadoA1.name,
            });

            this.formulario.value.fileCertificadoA1 = $file.target.files[0];
            this.formulario.value.certificado_id = response.data.file_id;
            this.fileIdCertificadoA1 = response.data.file_id;
            this.formulario.patchValue({
                certificado_id: response.data.file_id,
            });
            this.formulario.controls.certificado_senha.enable();
        } else {
            this.fileCertificadoA1 = null;
            this.exibirMensagem('Atenção', "Tipo do certificado invalido!");
        }
    }

    exibirMensagem(titulo: string, texto: string, classe: string = 'custom-snackbar') {
        this.snackBar.open(texto, '', {
            duration: 4000,
            horizontalPosition: 'center',
            verticalPosition: 'top',
            panelClass: [classe],
        });
    }

    async onFileCertificadoCAsInput($file) {
        this.fileCertificadoCAs = $file.target.files[0];
        const response = await gedUpload({
            file: this.fileCertificadoCAs,
            fileName: this.fileCertificadoCAs.name,
        });

        this.formulario.value.fileCertificadoCAs = $file.target.files[0];
        this.formulario.value.certificado_ca_id = response.data.file_id;
        this.fileIdCertificadoCAs = response.data.file_id;
        this.formulario.patchValue({
            certificado_ca_id: response.data.file_id,
        });
    }

    async carregarCertificadosAtuais() {
        const {certificado_a1_id, certificado_cas_id, nome_certificado_a1, nome_certificado_cas} =
            await apiESocialBuscarCertificadoAtual();
        this.formulario.value.certificado_ca_id = certificado_cas_id;
        this.formulario.value.certificado_id = certificado_a1_id;
        this.fileCertificadoA1 = {name: nome_certificado_a1}
        this.fileCertificadoCAs = {name: nome_certificado_cas}
    }
}

import { Component, OnDestroy } from "@angular/core";
import { Subject } from "rxjs";

@Component({
    selector: 'app-base-component',
    template: `<div>base works!!</div>`
})
export class BaseComponent implements OnDestroy {
    /**
    * OPÇÃO 1:
    * subscription com a função de evitar memory leak na aplicação.
    * Manualmente destruimos a assinatura quando o componente for destruído.
    * Mais informações: https://blog.angularindepth.com/the-best-way-to-unsubscribe-rxjs-observable-in-the-angular-applications-d8f9aa42f6a0
    *
    * Implementação:
    * private subscription: Subscription;  // Opção 1
    * 
    * this.subscription = this.loadingService.consultarValorLoading().subscribe((state: LoadingState) => {
    *   this.loading = state.loading;
    * });

    * ngOnDestroy() {
    *   this.subscription.unsubscribe();
    * }
    */

    /**
     * OPÇÃO 2:
     * Gerenciará sua assinatura com base na vida útil do elemento DOM ao qual está associado.
     * O canal assíncrono fará uma nova assinatura onde quer que seja declarado.
     * Use "as" para reutilizar o valor fornecido.
     * 
     * Implementação:
     * <div *ngIf="observable$ | async as data">
     *   {{ data }}
     * </div>
     */

    /**
     * OPÇÃO 3:
     * take, takeUntil e takeWhile gerenciarão uma assinatura automaticamente com base nas condições atendidas.
     * Por exemplo, takeUntil utilizará um observável como argumento e manterá uma assinatura até que esse observável emita um valor.
     * Mais informações: https://itnext.io/angular-rxjs-detecting-memory-leaks-bdd312a070a0
     *                   https://medium.com/@maciekprzybylski/remember-to-unsubscribe-from-streams-in-your-angular-components-caf0bedd6ac2
     * Leitura complementar: https://blog.angulartraining.com/how-to-automatically-unsubscribe-your-rxjs-observables-tutorial-2f98b0560298
     * principalmente a parte dos porquês.
     */
    unsubscribe: Subject<void> = new Subject<void>();

    /**
     * Cancela as assinaturas (observables) para garantir que não haja
     * vazamentos de memória - (Memory Leaks).
     * Cancela a inscrição de todas as subscrições.
     */
    ngOnDestroy(): void {
        this.unsubscribe.next();
        this.unsubscribe.complete();
    }
}

