import { Component, Inject } from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { MAT_DIALOG_DATA, MatDialog, MatDialogRef } from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';
import { MpmtFormularioComponent } from 'components/mpmt-formulario/mpmt-formulario.component';
import { apiDiariasBeneficiarios } from 'api/diarias/api-diaria-beneficiarios.service';
import { apiDiariasViagemCancelar } from 'api/diarias/api-diarias-nova-viagem-cancelar.service';

class CancelarDiariaComponentData {
    viagem_id: number;
    solicitante: boolean;
    currentUser: any;
    onClose?: Function;
}

@Component({
    selector: 'cancelar-diaria',
    templateUrl: 'cancelar-diaria.component.html',
})
export class CancelarDiariaComponent extends MpmtFormularioComponent<CancelarDiariaComponentData> {

    lista_beneficiarios: any[] =[];

    protected formulario = new FormGroup({
        beneficiarios: new FormControl<number[]>(null, [Validators.required]),        
    });

    constructor(
        @Inject(MAT_DIALOG_DATA)
        protected data: CancelarDiariaComponentData,
        protected dialogRef: MatDialogRef<CancelarDiariaComponentData>,
        protected snackBar: MatSnackBar,
        public dialog: MatDialog,
    ) {
        super(data, snackBar, dialogRef);
    }

    ngOnInit() {
        this.carregarBeneficiarios();
    }

    protected async confirmarFormulario() {
        if (!this.formularioValido) return;

        const { beneficiarios } = this.formulario.value;

        let result = null

        try {

            result = await apiDiariasViagemCancelar({
                id: this.data.viagem_id,
                beneficiarios_ids: beneficiarios
            });

            const resultado = result.data?.datail || "Solicitação Cancelada"

            this.exibirMensagem('', resultado, 'sucess-snackbar')

            this.fecharFormulario();
            this.data?.onClose();

        } catch (e: any) {
            const detalheErro = e?.response?.data?.error || '' ||  e?.response?.data?.datail;
            const texto = ` ${detalheErro}`;
            this.exibirMensagem(
                'Atenção',
                texto
            );
        }
    }

    public async carregarBeneficiarios() {
        try {
            this.lista_beneficiarios = (await apiDiariasBeneficiarios(
                {
                    viagem_id:this.data.viagem_id
                }
            )).results;
        } catch (error) {
            console.error('Erro ao carregar os beneficiários:', error);
        }
    }

    protected opcao_ativa(beneficiario): boolean{
        if(beneficiario.fluxo_unicode.toUpperCase().includes("CANCELADO")){
            return true
        }

        if(this.data.solicitante){
            return false
        }
        if(beneficiario.servidor == this.data.currentUser.id){
            return false
        }

        return true
    }


}

import { Component, Inject, OnInit } from '@angular/core';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';
import { apiBeneficiariosPorFluxo } from 'api/diarias/api-diaria-beneficiarios-por-fluxo.service';
import { apiCienciaCancelamentoDiarias } from 'api/diarias/aprovacoes-beneficiario/api-ciencia-cancelamento.service';

export class CienciaCancelamentoComponentData {
    titulo: string;
    fluxoID: number;
    viagemID: number;
    onClose?: Function;
}

@Component({
    selector: 'ciencia-cancelamento-diarias',
    templateUrl: './ciencia-cancelamento-diarias.component.html',
})
export class CienciaCancelamentoComponent implements OnInit{ 
    beneficiarios: any[] = [];
    constructor(
        @Inject(MAT_DIALOG_DATA) 
        protected data: CienciaCancelamentoComponentData,
        protected dialogRef: MatDialogRef<CienciaCancelamentoComponentData>,
        protected snackBar: MatSnackBar,
    ) {}

    async ngOnInit() {
        await this.carregarBeneficiarios();
    }

    protected async carregarBeneficiarios() {
        try {
            const payload = { fluxo_id: this.data.fluxoID, viagem_id: this.data.viagemID };
            const response = await apiBeneficiariosPorFluxo(payload);
            this.beneficiarios = response.results;
        } catch (error) {
            const detalheErro = error?.response?.data?.message || 'Erro ao carregar beneficiários.';
            this.exibirMensagem('Erro', detalheErro);
        }

    }

    protected async darCiencia() {
        try {
            const beneficiariosIds = this.beneficiarios.map((beneficiario) => beneficiario.id);

            const payload = {
                beneficiarios: beneficiariosIds,
            };
            await apiCienciaCancelamentoDiarias(payload);

            this.dialogRef.close(true);
        } catch (error) {
            const detalheErro = error?.response?.data?.message || 'Erro ao realizar ciência de cancelamento.';
            this.exibirMensagem('Erro', detalheErro);
        }
    }

    protected exibirMensagem(titulo: string, texto: string, classe: string = 'custom-snackbar') {
        this.snackBar.open(texto, '', {
            duration: 4000,
            horizontalPosition: 'center',
            verticalPosition: 'top',
            panelClass: [classe],
        });
    }

    protected fecharFormulario() {
        this.dialogRef.close();
    }
}

import { Component, OnDestroy, OnInit, ViewEncapsulation } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Subject, takeUntil } from 'rxjs';
import { FuseMediaWatcherService } from '@fuse/services/media-watcher';
import {
    FuseNavigationService,
    FuseVerticalNavigationComponent,
} from '@fuse/components/navigation';
import { Navigation } from 'core/navigation/navigation.types';
import { NavigationService } from 'core/navigation/navigation.service';
import { environment } from 'environments/environment';
import { AtualizacaoCadastralEmailComponent } from 'apps/vdf/atualizacao-cadastral/atualizacao-cadastral-email/atualizacao-cadastral-email.component';

@Component({
    selector: 'classic-layout',
    templateUrl: './classic.component.html',
    encapsulation: ViewEncapsulation.None,
})
export class ClassicLayoutComponent implements OnInit, OnDestroy {
    isScreenSmall: boolean;
    navigation: Navigation;
    private _unsubscribeAll: Subject<any> = new Subject<any>();
    navigationAppearance: 'default' | 'dense' = 'default';
    public version_app: string = environment.version_app;
    public name_app: string = environment.name_app;

    /**
     * Constructor
     */
    constructor(
        private _activatedRoute: ActivatedRoute,
        private _router: Router,
        private _navigationService: NavigationService,
        private _fuseMediaWatcherService: FuseMediaWatcherService,
        private _fuseNavigationService: FuseNavigationService,
        private atualizacaoCadastralEmailComponent: AtualizacaoCadastralEmailComponent
    ) {}

    // -----------------------------------------------------------------------------------------------------
    // @ Accessors
    // -----------------------------------------------------------------------------------------------------

    /**
     * Getter for current year
     */
    get currentYear(): number {
        return new Date().getFullYear();
    }

    // -----------------------------------------------------------------------------------------------------
    // @ Lifecycle hooks
    // -----------------------------------------------------------------------------------------------------

    /**
     * On init
     */
    ngOnInit(): void {
        // Subscribe to navigation data
        this._navigationService.navigation$
            .pipe(takeUntil(this._unsubscribeAll))
            .subscribe((navigation: Navigation) => {
                this.navigation = navigation;
            });

        // Subscribe to media changes
        this._fuseMediaWatcherService.onMediaChange$
            .pipe(takeUntil(this._unsubscribeAll))
            .subscribe(({ matchingAliases }) => {
                // Check if the screen is small
                this.isScreenSmall = !matchingAliases.includes('md');
            });

        this.atualizacaoCadastralEmailComponent.abrirSeNecessario();
    }

    /**
     * On destroy
     */
    ngOnDestroy(): void {
        // Unsubscribe from all subscriptions
        this._unsubscribeAll.next(null);
        this._unsubscribeAll.complete();
    }

    // -----------------------------------------------------------------------------------------------------
    // @ Public methods
    // -----------------------------------------------------------------------------------------------------

    /**
     * Toggle navigation
     *
     * @param name
     */
    toggleNavigation(name: string): void {
        // Get the navigation
        const navigation =
            this._fuseNavigationService.getComponent<FuseVerticalNavigationComponent>(
                name
            );

        if (navigation) {
            // Toggle the opened status
            navigation.toggle();
        }
    }

    /**
     * Toggle the navigation appearance
     */
    toggleNavigationAppearance(): void {
        this.navigationAppearance =
            this.navigationAppearance === 'default' ? 'dense' : 'default';
    }

    goAthenas() {
        window.open('https://athenas.mpmt.mp.br/', '_blank');
    }

    irAjuda() {
        window.open(
            'https://mp-mt.atlassian.net/wiki/spaces/MAN/pages/6102901/Vida+Funcional',
            '_blank'
        );
    }
}

