                responsavel_id: data.configuracao?.responsavel_id,
                // responsavel: data.configuracao?.,
                responsavel_sowfware_house_id: data.configuracao?.responsavel_sowfware_house_id,
                // responsavel_sowfware_house: data.configuracao?.,
                tabela_iniciais: data.configuracao?.tabela_iniciais,
                nao_periodicos: data.configuracao?.nao_periodicos,
                periodicos: data.configuracao?.periodicos,
                sst: data.configuracao?.sst,
                inicio_vigencia: data.configuracao?.inicio_vigencia,
                fim_vigencia: data.configuracao?.fim_vigencia,
                data_corte_s2231: data.configuracao?.data_corte_s2231,
            })

            this.carregarEventosJaCadastrados();
            this.carregarEmpregador();
            this.carregarResponsavel();
            this.carregarResponsavelSoftware();
            this.carregarServidoresGerados();
        }
    }

    carregarEventos(keyword?: string) {
        apiESocialListarEventos({keyword})
            .then(response => {
                this.eventos = response.results.map(item => {return {label: item.descricao, value: item.id}})
            });
    }

    protected formulario = new FormGroup({
        id: new FormControl<number>(null, []),
        ambiente: new FormControl<number>(null, [Validators.required]),
        layout_versao: new FormControl<string>(null, [Validators.pattern('^[0-9]+\\.[0-9]+$')]),
        webservice_envio: new FormControl<string>(null, [Validators.required]),
        webservice_consulta: new FormControl<string>(null, [Validators.required]),
        nome_schema_envio: new FormControl<string>(null, [Validators.required]),
        nome_schema_consulta: new FormControl<string>(null, [Validators.required]),
        url_envio: new FormControl<string>(null, [Validators.required]),
        url_consulta: new FormControl<string>(null, [Validators.required]),
        envio_fila: new FormControl<boolean>(false, [Validators.required]),
        servidores_gerados_ids: new FormControl<number[]>([], []),
        eventos_gerados_ids: new FormControl<number[]>([], []),
        orgao_empregador_id: new FormControl<number>(null, [Validators.required]),
        orgao_empregador: new FormControl<any>(null, [Validators.required]),
        responsavel_id: new FormControl<number>(null, [Validators.required]),
        responsavel: new FormControl<any>(null, [Validators.required]),
        responsavel_sowfware_house_id: new FormControl<number>(null, [Validators.required]),
        responsavel_sowfware_house: new FormControl<any>(null, [Validators.required]),
        tabela_iniciais: new FormControl<string | null>(null, [Validators.required]),
        nao_periodicos: new FormControl<string | null>(null, [Validators.required]),
        periodicos: new FormControl<string | null>(null, [Validators.required]),
        sst: new FormControl<string | null>(null, [Validators.required]),
        inicio_vigencia: new FormControl<string | null>(null, [Validators.required]),
        fim_vigencia: new FormControl<string | null>(null, []),
        data_corte_s2231: new FormControl<string | null>(null, [Validators.required]),

        //campos não utilizados mas que seram mandados como []
        eventos_nao_enviados_ids: new FormControl<number[]>([], []),
        servidores_nao_gerados_ids: new FormControl<number[]>([], []),
        beneficiarios_gerados_ids: new FormControl<number[]>([], []),
        beneficiarios_nao_gerados_ids: new FormControl<number[]>([], []),
    });

    async goConfirm() {
        this.converterDatas()

        const { id,
            ambiente,
            layout_versao,
            webservice_envio,
            webservice_consulta,
            nome_schema_envio,
            nome_schema_consulta,
            url_envio,
            url_consulta,
            envio_fila,
            servidores_gerados_ids,
            eventos_gerados_ids,
            orgao_empregador_id,
            responsavel_id,
            responsavel_sowfware_house_id,
            tabela_iniciais,
            nao_periodicos,
            periodicos,
            sst,
            inicio_vigencia,
            fim_vigencia,
            data_corte_s2231,
            eventos_nao_enviados_ids,
            servidores_nao_gerados_ids,
            beneficiarios_gerados_ids,
            beneficiarios_nao_gerados_ids
        } = this.formulario.value;

        try {
            this.isLoading = true;
            await apiESocialEditarConfiguracao({
                id,
                ambiente,
                layout_versao,
                webservice_envio,
                webservice_consulta,
                nome_schema_envio,
                nome_schema_consulta,
                url_envio,
                url_consulta,
                envio_fila,
                servidores_gerados_ids,
                eventos_gerados_ids,
                orgao_empregador_id,
                responsavel_id,
                responsavel_sowfware_house_id,
                tabela_iniciais,
                nao_periodicos,
                periodicos,
                sst,
                inicio_vigencia,
                fim_vigencia,
                data_corte_s2231,
                eventos_nao_enviados_ids,
                servidores_nao_gerados_ids,
                beneficiarios_gerados_ids,
                beneficiarios_nao_gerados_ids
            });

            this.dialogRef.close();
        } catch (e: any) {
            this.message = e?.response?.data?.message;
        } finally {
            this.isLoading = false;
        }
    }

    get isValid() {
        return this.formulario.valid;
    }

    eventosSelecionados($event: string[]) {
        let eventos = $event.map(event => Number(event))
        this.formulario.controls.eventos_gerados_ids.setValue(eventos);
    }

    filterEventos($event: string) {
        this.carregarEventos($event);
    }

    vincularServidores() {
        this.dialog.open(VincularServidoresDialogComponent, {
            data: <VincularServidoresDialogComponentData>{
                form: this.formulario
            },
            width: '80%',
            height: '90%',
        });
    }

    loadUnidadesAdministrativas(keyword?: string) {
        this.datasourceUnidadesAdministrativas.load({ keyword: keyword, per_page: 12 });
    }
    loadResponsaveis(keyword?: string) {
        this.dataSourceResponsaveis.load({ keyword: keyword, per_page: 12 });
    }
    loadResponsaveisSoftwareHouse(keyword?: string) {
        this.dataSourceResponsaveisSoftwareHouse.load({ keyword: keyword, per_page: 12 });
    }

    displayFnUnidade(unidade: { nome: string }): string {
        return unidade && unidade.nome ? unidade.nome : '';
    }

    displayFn(obj) {
        return obj?.name;
    }

    onResponsavelSoftwareSelected(value: any) {
        this.formulario.patchValue({
            responsavel_sowfware_house_id: value?.pk
        })
    }

    onResponsavelSelected(value: any) {
        this.formulario.patchValue({
            responsavel_id: value?.pk
        })
    }

    onEmpregadorSelected(value: any) {
        this.formulario.patchValue({
            orgao_empregador_id: value?.id
        })
    }

    private converterDatas() {
        if (this.formulario.controls.inicio_vigencia.value) {
            this.formulario.controls.inicio_vigencia.setValue(moment(this.formulario.controls.inicio_vigencia.value).format('YYYY-MM-DD'))
        }

        if (this.formulario.controls.fim_vigencia.value) {
            this.formulario.controls.fim_vigencia.setValue(moment(this.formulario.controls.fim_vigencia.value).format('YYYY-MM-DD'))
        }

        if (this.formulario.controls.data_corte_s2231.value) {
            this.formulario.controls.data_corte_s2231.setValue(moment(this.formulario.controls.data_corte_s2231.value).format('YYYY-MM-DD'))
        }

        if (this.formulario.controls.nao_periodicos.value) {
            this.formulario.controls.nao_periodicos.setValue(moment(this.formulario.controls.nao_periodicos.value).format('YYYY-MM-DD'))
        }

        if (this.formulario.controls.periodicos.value) {
            this.formulario.controls.periodicos.setValue(moment(this.formulario.controls.periodicos.value).format('YYYY-MM-DD'))
        }

        if (this.formulario.controls.sst.value) {
            this.formulario.controls.sst.setValue(moment(this.formulario.controls.sst.value).format('YYYY-MM-DD'))
        }

        if (this.formulario.controls.tabela_iniciais.value) {
            this.formulario.controls.tabela_iniciais.setValue(moment(this.formulario.controls.tabela_iniciais.value).format('YYYY-MM-DD'))
        }
    }

    private carregarEventosJaCadastrados() {
        if(this.data?.configuracao?.eventos_gerados_detalhes) {
            this.eventosJaCadastrados = this.data.configuracao.eventos_gerados_detalhes.map(item => {return {label: item.descricao, value: item.id}})
            this.formulario.patchValue({
                eventos_gerados_ids: this.eventosJaCadastrados.map(item => item.value)
            })
        }
    }

    private carregarEmpregador() {
        if(this.data?.configuracao?.orgao_empregador_id && this.data?.configuracao?.orgao_empregador_display) {
            this.formulario.patchValue({
                orgao_empregador: {id: this.data?.configuracao?.orgao_empregador_id, nome: this.data?.configuracao?.orgao_empregador_display}
            })
        }
    }

    private carregarResponsavel() {
        if(this.data?.configuracao?.responsavel_id && this.data?.configuracao?.responsavel) {
            this.formulario.patchValue({
                responsavel: {pk: this.data?.configuracao?.responsavel_id, name: this.data?.configuracao?.responsavel}
            })
        }
    }

    private carregarResponsavelSoftware() {
        if(this.data?.configuracao?.responsavel_sowfware_house_id && this.data?.configuracao?.responsavel_sowfware_house) {
            this.formulario.patchValue({
                responsavel_sowfware_house: {pk: this.data?.configuracao?.responsavel_sowfware_house_id, name: this.data?.configuracao?.responsavel_sowfware_house}
            })
        }
    }

    private carregarServidoresGerados() {
        if(this.data?.configuracao?.servidores_gerados_detalhes) {
            this.formulario.patchValue({
                servidores_gerados_ids: this.data.configuracao.servidores_gerados_detalhes.map(item => item.pk)
            })
        }
    }
}

import { Component, Inject, SecurityContext } from "@angular/core";
import { MatDialogRef, MAT_DIALOG_DATA } from "@angular/material/dialog";
import { DomSanitizer } from "@angular/platform-browser";
import { Notification } from "../notifications.types";
import { environment } from 'environments/environment';

const icone = `<mat-icon role="img" class="mat-icon icon-size-16 text-sky-500" data-mat-icon-type="svg">
<svg viewBox="0 0 24 24" fit="" height="100%" width="100%" preserveAspectRatio="xMidYMid meet" 
focusable="false">
<path d="M0 0h24v24H0z" fill="none"></path>
<path d="M19.35 10.04C18.67 6.59 15.64 4 12 4 9.11 4 6.6 5.64 5.35 8.04 2.34 8.36 0 10.91 0 14c0 3.31 
2.69 6 6 6h13c2.76 0 5-2.24 5-5 0-2.64-2.05-4.78-4.65-4.96zM17 13l-5 5-5-5h3V9h4v4h3z">
</path></svg></mat-icon>`;


@Component({
  selector: 'conteudo',
  templateUrl: 'conteudo.component.html'
})
export class ConteudoDialog {
  conteudo
  urlBase = environment.url_base;
  constructor(
    public dialogRef: MatDialogRef<ConteudoDialog>,
    @Inject(MAT_DIALOG_DATA) public data: Notification,
    private sanitized: DomSanitizer
  ) {
    let conteudo = this.data.conteudo;
    if (conteudo.includes("target=\"_blank\">Clique aqui</a>")) {
      conteudo = conteudo.replace("<div style=\"font-family: Tahoma, Arial, Helvetica, sans-serif; font-size: 10pt;\">", 
      "<div style=\"font-family: Tahoma, Arial, Helvetica, sans-serif;font-size: 10pt;text-align: center;\">");
      conteudo = conteudo.replace("<a ", '<a onclick=\"getElementById(\'btnFecharModalNotificacao\').click()\" ');
      conteudo = conteudo.replace("Clique aqui", icone);
      conteudo = conteudo.replace("</a> para baixar o arquivo.</p>", "<br>Baixar o arquivo</a></p><br>");  
    }
    let conteudoSemQuebrasDeLinha = conteudo.replace(/[\r\n]/g, "");
    this.conteudo = this.sanitized.bypassSecurityTrustHtml(conteudoSemQuebrasDeLinha);
  }

  onNoClick(): void {
    this.dialogRef.close();
  }
}

import { Component, Inject, OnInit } from '@angular/core';
import { FormArray, FormBuilder, FormControl, FormGroup, Validators } from '@angular/forms';
import { DateAdapter } from '@angular/material/core';
import { MAT_DIALOG_DATA, MatDialog, MatDialogRef } from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';
import { MpmtFormularioComponent } from 'components/mpmt-formulario/mpmt-formulario.component';
import { DestinosService } from './diarias-destinos.service';
import moment from 'moment';
import { apiVeiculoMotoristaDaaCriar, Payload } from 'api/diarias/analise-beneficiario/api-analise-daa-veicuo-motorista-criar.service';
import { apiDiariasMotoristasService } from 'api/diarias/api-diarias-motoristas.service';
import { NovoDadosBancariosComponent } from 'apps/vdf/minhas-diarias/novo-dados-bancarios/novo-dados-bancarios.component';
import { DatePipe } from '@angular/common';

interface VeiculoForm {
    capacidade_passageiros: FormControl<number | null>;
    marca: FormControl<string>;
    modelo: FormControl<string>;
    placa: FormControl<string>;
}

interface MotoristaForm {
    motorista: FormControl<number | null>;
}

class DaaCriarMotoristaVeiculoData {
    destinoId: number;
    viagemID: number;
    comMotorista: boolean;
    veiculoDaa: boolean;
    onClose?: Function;
}

@Component({
    selector: 'daa-motorista-veiculo-criar',
    templateUrl: 'daa-motorista-veiculo-criar.component.html',
    providers:[DatePipe]
})

export class DaaCriarMotoristaVeiculoComponent extends MpmtFormularioComponent<DaaCriarMotoristaVeiculoData> implements OnInit {
    filtros = new FormGroup({
        palavra_chave: new FormControl<string>('', [])
    });

    servidores: any[] = [];
    destinos: any[] = [];
    beneficiarios: any[] = [];
    motoristas: any[] = [];
    contaSelecionada: any = null;
    destinosDistintos: any[] = [];
    exibirBotaoSelecionarDadosBancarios = false;

    formularioVeiculo: FormGroup<VeiculoForm>;
    formularioMotorista: FormGroup<MotoristaForm>;
    formularioDestinosDistintos: FormArray;

    constructor(
        @Inject(MAT_DIALOG_DATA)
        protected data: DaaCriarMotoristaVeiculoData,
        protected dialogRef: MatDialogRef<DaaCriarMotoristaVeiculoData>,
        protected snackBar: MatSnackBar,
        protected dateAdapter: DateAdapter<Date>,
        protected service: DestinosService,
        public dialog: MatDialog,
        private fb: FormBuilder
    ) {
        super(data, snackBar, dialogRef);
        this.dateAdapter.setLocale('pt-BR');
        this.formularioVeiculo = new FormGroup<VeiculoForm>({} as VeiculoForm);
        this.formularioMotorista = new FormGroup<MotoristaForm>({} as MotoristaForm);
    }

    async ngOnInit() {
        this.service.viagemID = this.data?.viagemID;
        this.service.comMotorista = this.data?.comMotorista;
        this.service.veiculoDaa = this.data?.veiculoDaa;

        this.montarFormulario();

        this.configurarColunas();
        await this.service.recarregarListagem();
        this.preSelecionarDestino();

        await this.carregarMotoristas();

        this.service.destinosDistintos$.subscribe((destinos) => {
            this.initDestinosFormArray(destinos);
        });
    }

    private montarFormulario() {
        if (this.data.veiculoDaa) {
            this.formularioVeiculo = new FormGroup<VeiculoForm>({
                capacidade_passageiros: new FormControl<number | null>(null, [Validators.required]),
                marca: new FormControl<string>('', [Validators.required]),
                modelo: new FormControl<string>('', [Validators.required]),
                placa: new FormControl<string>('', [Validators.required]),
            });
        }

        if (this.data.comMotorista) {
            this.formularioMotorista = new FormGroup<MotoristaForm>({
                motorista: new FormControl<number | null>(null, [Validators.required]),
            });
        }

        this.formularioDestinosDistintos = this.fb.array([]);
        this.service.destinosDistintos$.subscribe((destinos) => {
            this.initDestinosFormArray(destinos);
        });
    }

    private initDestinosFormArray(destinos: any[]) {
        this.formularioDestinosDistintos.clear();
        destinos.forEach(destino => {
            const destinoGroup = this.fb.group({
                ids: [destino.ids],
                origem: `${destino.uf_origem_sigla} / ${destino.municipio_origem_display}`,
                destino: `${destino.uf_destino_sigla} / ${destino.municipio_destino_display}`,
                data: [this.formatarData(destino.data), Validators.required],
                hora: [this.obterHora(destino.data), Validators.required]
            });
            this.formularioDestinosDistintos.push(destinoGroup);
        });
    }

    protected async preSelecionarDestino() {
        try {
            this.service.listagem$.subscribe((itens) => {
                const destinoSelecionado = itens.find(item => item.id === this.data.destinoId);
                if (destinoSelecionado) {
                    this.service.adicionarItemSelecionado(destinoSelecionado);
                }
            });
        } catch (error) {
            console.error('Erro ao pré-selecionar o destino:', error);
        }
    }

    protected async carregarMotoristas() {
        try {
            const respostaMotoristas = await apiDiariasMotoristasService({});
            this.motoristas = respostaMotoristas.results;
        } catch (error) {
            console.error('Erro ao carregar motoristas:', error);
            this.exibirMensagem('Erro', 'Não foi possível carregar a lista de motoristas.');
        }
    }

    abrirModalDadosBancarios() {
        const dialogRef = this.dialog.open(NovoDadosBancariosComponent, {
            data: { 
                servidor_id: this.formularioMotorista.value.motorista,
                beneficiario_id: null,
                contaSelecionada: this.contaSelecionada,
            }
        });

        dialogRef.afterClosed().subscribe(result => {
            if (result && result.conta) {
                this.contaSelecionada = result.conta;
            }
        });
    }

    onMotoristaChange() {
        const motoristaSelecionado = this.formularioMotorista.value.motorista;
        if (motoristaSelecionado) {
            this.exibirBotaoSelecionarDadosBancarios = true;
            this.contaSelecionada = null;
        } else {
            this.exibirBotaoSelecionarDadosBancarios = false; 
        }
    }

    private configurarColunas() {
        this.service.configurarColunas([
            {
                codigo: 'checkbox',
                titulo: '',
                visivel: true,
                tipo: 'CHECKBOX',
                ordenavel: false,
            },
            {
                codigo: 'beneficiario_unicode',
                titulo: 'Beneficiário',
                visivel: true,
                ordenavel: false,
            },
            {
                codigo: 'uf_origem_display',
                titulo: 'Origem',
                visivel: true,
                ordenavel: false,
                transformarValor:  (linha: any) => {
                    return linha.uf_origem_sigla + "/" + linha.municipio_origem_display;
                }
            },
            {
                codigo: 'uf_destino_display',
                titulo: 'Destino',
                visivel: true,
                ordenavel: false,
                transformarValor:  (linha: any) => {
                    return linha.uf_destino_sigla + "/" + linha.municipio_destino_display;
                }
            },
            {
                codigo: 'data',
                titulo: 'Data',
                tipo:'DATA',
                visivel: true,
                ordenavel: false,
            },
            {
                codigo: 'hora',
                titulo: 'Horário',
                visivel: true,
                ordenavel: false,
                transformarValor:  (linha: any) => {
                    return linha.data ? moment(linha.data).format('HH:mm') : '';
                }
            },
            {
                codigo: 'distancia_km',
                titulo: 'Distância em km',
                visivel: true,
                ordenavel: false,
                transformarValor:  (linha: any) => {
                    return linha.distancia_km ? linha.distancia_km + " km" : ' - ';
                }
            },
            {
                codigo: 'evento_display',
                titulo: 'Evento',
                visivel: false,
                ordenavel: false,
            },
        ]);
    }

    protected async confirmarFormulario() {
        if (!this.formularioValido) return;

        if (!this.validarCapacidadeVeiculo()) return;

        if (this.data.comMotorista && !this.contaSelecionada) {
            this.exibirMensagem('Erro', 'Por favor, selecione os dados bancários para o motorista.');
            return;
        }

        const veiculoData = this.formularioVeiculo.value;
        const motoristaData = {
            motorista: this.formularioMotorista.value.motorista,
            conta_bancaria_pgto: this.contaSelecionada
        };

        const destinosData = this.formularioDestinosDistintos.value.map(destino => {
            const data = destino.data;
            const hora = destino.hora;
            const dataHora = `${data}T${hora}:00`;
            return { ids: destino.ids, dataHora: dataHora };
        });

        const payload: Payload = {
            veiculo: {
                placa: veiculoData.placa,
                marca: veiculoData.marca,
                modelo: veiculoData.modelo,
                capacidade_passageiros: veiculoData.capacidade_passageiros,
            },
            motorista: motoristaData,
            destinos: destinosData,
        };

        try {
            const response = await apiVeiculoMotoristaDaaCriar(payload);
            this.fecharFormulario();
            this.data?.onClose();
        } catch (e: any) {
            console.error(e);
            this.exibirMensagem('Erro', 'Não foi possível realizar a operação.');
        }
    }

    protected validarCapacidadeVeiculo(): boolean {
        const destinosSelecionados = this.service.obterItensSelecionados();
        const beneficiariosSelecionados = destinosSelecionados.map(destino => destino.beneficiario);

        const beneficiariosUnicos = new Set(beneficiariosSelecionados);
        const quantidadeBeneficiarios = beneficiariosUnicos.size;

        const capacidadeVeiculo = this.formularioVeiculo.value.capacidade_passageiros;

        const capacidadeDisponivelParaBeneficiarios = capacidadeVeiculo - 1;

        if (quantidadeBeneficiarios > capacidadeDisponivelParaBeneficiarios) {
            this.exibirMensagem(
                'Erro',
                `A capacidade do veículo é menor do que a quantidade de beneficiários selecionados. O veículo pode acomodar no máximo ${capacidadeDisponivelParaBeneficiarios} beneficiários.`
            );
            return false;
        }
        return true;
    }

    formatarData(data: string): string {
        return moment(data).format('YYYY-MM-DD');
    }

    obterHora(data: string): string {
        return moment(data).format('HH:mm');
    }

    atualizarDataHora(destino: any, novaData: string, novaHora: string) {
        const novaDataHora = moment(`${novaData}T${novaHora}`).toISOString();
        destino.data = novaDataHora;
    }

    protected fecharFormulario() {
        this.service.limparItensSelecionados();
        this.dialogRef.close();
    }

    get formularioValido(): boolean {
        const destinosSelecionados = this.service.obterItensSelecionados();
        return this.formularioVeiculo.valid && this.formularioMotorista.valid && destinosSelecionados.length > 0;
    }

    protected exibirMensagem(titulo: string, mensagem: string) {
        this.snackBar.open(mensagem, titulo, { duration: 3000 });
    }
}

import { Component, Inject, OnInit } from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { DateAdapter } from '@angular/material/core';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';
import { apiBeneficiarioDaaPassagemCriar } from 'api/diarias/analise-beneficiario/api-analise-daa-passagem-criar.service';
import { MpmtFormularioComponent } from 'components/mpmt-formulario/mpmt-formulario.component';

class DaaCriarPassagemAereaData {
    destinoId: number;
    onClose?: Function;
}

@Component({
    selector: 'daa-passagem-aerea-criar',
    templateUrl: 'daa-passagem-aerea-criar.component.html',
})
export class DaaCriarPassagemAereaComponent extends MpmtFormularioComponent<DaaCriarPassagemAereaData> implements OnInit {
    anexos: any[] = [];

    protected formulario = new FormGroup({
        empresa: new FormControl<string>('', [Validators.required]),
        aeroporto: new FormControl<string>('', [Validators.required]),
        numeroBilhete: new FormControl<number>(null, [Validators.required]),
        dataVoo: new FormControl<Date>(null, [Validators.required]),
        horaSaidaVoo: new FormControl<string>(null, [Validators.required]),
    });

    ngOnInit() {
        super.ngOnInit();
    }

    constructor(
        @Inject(MAT_DIALOG_DATA)
        protected data: DaaCriarPassagemAereaData,
        protected dialogRef: MatDialogRef<DaaCriarPassagemAereaData>,
        protected snackBar: MatSnackBar,
        protected dateAdapter: DateAdapter<Date>,
    ) {
        super(data, snackBar, dialogRef);
        this.dateAdapter.setLocale('pt-BR');
    }

    protected async confirmarFormulario() {
        if (!this.formularioValido) return;

        const { empresa, aeroporto, numeroBilhete, dataVoo, horaSaidaVoo } = this.formulario.value;
        const anexos = this.anexos;
        const dataFormatada = new Date(dataVoo);
        const horaFormatada = horaSaidaVoo.split(':');

        dataFormatada.setHours(parseInt(horaFormatada[0]), parseInt(horaFormatada[1]));

        const utcDatetime = new Date(dataFormatada.getTime() - dataFormatada.getTimezoneOffset() * 60000);

        try {
            const response = await apiBeneficiarioDaaPassagemCriar({
                destino: this.data.destinoId,
                empresa,
                aeroporto,
                numeroBilhete,
                dataHoraVoo: utcDatetime,
                anexos,
            });

            this.resetarFormulario();
            this.fecharFormulario();
            this.data?.onClose();

        } catch (e: any) {
            console.error(e)
            const detalheErro = e?.response?.data?.message || 'Não foi possível realizar a operação.';
            this.exibirMensagem('Erro', detalheErro);
        }
    }

    protected async receberAnexos(dados: []) {
        this.anexos = dados;
    }

    get formularioValido(): boolean {
        return this.formulario.valid && this.anexos.length > 0;
    }
}

