                valor_estado, 
                valor_fora_estado, 
                valor_exterior, 
                dt_inicio_vigencia, 
                dt_fim_vigencia,
            });

            this.resetarFormulario();
            this.fecharFormulario();
            this.data?.onClose();
        } catch (e: any) {
            console.log(e);
            const detalheErro = e?.response?.data?.message || '';
            const texto = `Ocorreu um erro inesperado ao editar o valor. ${detalheErro}`;
            this.exibirMensagem(
                'Atenção',
                texto
            );
        }
    }
}

