fuse-alert {
    display: block;

    /* Common */
    .fuse-alert-container {
        position: relative;
        display: flex;
        padding: 16px;
        font-size: 14px;
        line-height: 1;

        /* All icons */
        .mat-icon {
            color: currentColor !important;
        }

        /* Icon */
        .fuse-alert-icon {
            display: flex;
            align-items: flex-start;

            .fuse-alert-custom-icon,
            .fuse-alert-default-icon {
                display: none;
                align-items: center;
                justify-content: center;
                border-radius: 50%;

                &:not(:empty) {
                    display: flex;
                    margin-right: 12px;
                }
            }

            .fuse-alert-default-icon {

                .mat-icon {
                    @apply icon-size-5;
                }
            }

            .fuse-alert-custom-icon {
                display: none;

                &:not(:empty) {
                    display: flex;

                    + .fuse-alert-default-icon {
                        display: none;
                    }
                }
            }
        }

        /* Content */
        .fuse-alert-content {
            display: flex;
            flex-direction: column;
            justify-content: center;
            line-height: 1;

            /* Title */
            .fuse-alert-title {
                display: none;
                font-weight: 600;
                line-height: 20px;

                &:not(:empty) {
                    display: block;

                    /* Alert that comes after the title */
                    + .fuse-alert-message {

                        &:not(:empty) {
                            margin-top: 4px;
                        }
                    }
                }
            }

            /* Alert */
            .fuse-alert-message {
                display: none;
                line-height: 20px;

                &:not(:empty) {
                    display: block;
                }
            }
        }

        /* Dismiss button */
        .fuse-alert-dismiss-button {
            position: absolute;
            top: 10px;
            right: 10px;
            width: 32px !important;
            min-width: 32px !important;
            height: 32px !important;
            min-height: 32px !important;
            line-height: 32px !important;

            .mat-icon {
                @apply icon-size-4;
            }
        }
    }

    /* Dismissible */
    &.fuse-alert-dismissible {

        .fuse-alert-container {

            .fuse-alert-content {
                margin-right: 32px;
            }
        }
    }

    &:not(.fuse-alert-dismissible) {

        .fuse-alert-container {

            .fuse-alert-dismiss-button {
                display: none !important;
            }
        }
    }

    /* Border */
    &.fuse-alert-appearance-border {

        .fuse-alert-container {
            position: relative;
            overflow: hidden;
            border-radius: 6px;
            @apply shadow-md bg-card;

            .fuse-alert-border {
                position: absolute;
                left: 0;
                top: 0;
                bottom: 0;
                width: 4px;
            }

            .fuse-alert-message {
                @apply text-gray-600;
            }
        }

        /* Primary */
        &.fuse-alert-type-primary {

            .fuse-alert-container {

                .fuse-alert-border {
                    @apply bg-primary;
                }

                .fuse-alert-title,
                .fuse-alert-icon {
                    @apply text-primary;
                }

                .dark & {
                    @apply bg-gray-700;

                    .fuse-alert-border {
                        @apply bg-primary-400;
                    }

                    .fuse-alert-title,
                    .fuse-alert-icon {
                        @apply text-primary-400;
                    }

                    .fuse-alert-message {
                        @apply text-gray-300;
                    }

                    code {
                        @apply bg-gray-400 text-gray-800;
                    }
                }
            }
        }

        /* Accent */
        &.fuse-alert-type-accent {

            .fuse-alert-container {

                .fuse-alert-border {
                    @apply bg-accent;
                }

                .fuse-alert-title,
                .fuse-alert-icon {
                    @apply text-accent;
                }

                .dark & {
                    @apply bg-gray-700;

                    .fuse-alert-border {
                        @apply bg-accent-400;
                    }

                    .fuse-alert-title,
                    .fuse-alert-icon {
                        @apply text-accent-400;
                    }

                    .fuse-alert-message {
                        @apply text-gray-300;
                    }

                    code {
                        @apply bg-gray-400 text-gray-800;
                    }
                }
            }
        }

        /* Warn */
        &.fuse-alert-type-warn {

            .fuse-alert-container {

                .fuse-alert-border {
                    @apply bg-warn;
                }

                .fuse-alert-title,
                .fuse-alert-icon {
                    @apply text-warn;
                }

                .dark & {
                    @apply bg-gray-700;

                    .fuse-alert-border {
                        @apply bg-warn-400;
                    }

                    .fuse-alert-title,
                    .fuse-alert-icon {
                        @apply text-warn-400;
                    }

                    .fuse-alert-message {
                        @apply text-gray-300;
                    }

                    code {
                        @apply bg-gray-400 text-gray-800;
                    }
                }
            }
        }

        /* Basic */
        &.fuse-alert-type-basic {

            .fuse-alert-container {

                .fuse-alert-border {
                    @apply bg-gray-600;
                }

                .fuse-alert-title,
                .fuse-alert-icon {
                    @apply text-gray-600;
                }

                .dark & {
                    @apply bg-gray-700;

                    .fuse-alert-border {
                        @apply bg-gray-400;
                    }

                    .fuse-alert-title,
                    .fuse-alert-icon {
                        @apply text-gray-400;
                    }

                    .fuse-alert-message {
                        @apply text-gray-300;
                    }

                    code {
                        @apply bg-gray-400 text-gray-800;
                    }
                }
            }
        }

        /* Info */
        &.fuse-alert-type-info {

            .fuse-alert-container {

                .fuse-alert-border {
                    @apply bg-blue-600;
                }

                .fuse-alert-title,
                .fuse-alert-icon {
                    @apply text-blue-700;
                }

                .dark & {
                    @apply bg-gray-700;

                    .fuse-alert-border {
                        @apply bg-blue-400;
                    }

                    .fuse-alert-title,
                    .fuse-alert-icon {
                        @apply text-blue-400;
                    }

                    .fuse-alert-message {
                        @apply text-gray-300;
                    }

                    code {
                        @apply bg-gray-400 text-gray-800;
                    }
                }
            }
        }

        /* Success */
        &.fuse-alert-type-success {

            .fuse-alert-container {

                .fuse-alert-border {
                    @apply bg-green-500;
                }

                .fuse-alert-title,
                .fuse-alert-icon {
