import { Component, OnInit } from '@angular/core';
import { FormControl, FormGroup } from '@angular/forms';
import { MatDialog } from '@angular/material/dialog';
import { GestaoPessoasGestaoVdfService } from './gestao-pessoas-gestao-vdf.service';

@Component({
    selector: 'gestao-pessoas-gestao-vdf',
    templateUrl: 'gestao-pessoas-gestao-vdf.component.html',
})
export class GestaoPessoasGestaoVdfComponent implements OnInit {
    filtros = new FormGroup({
        order_by: new FormControl<string>(null, []),
        palavra_chave: new FormControl<string>('', []),
        situacao: new FormControl<string>('ATIVO', []),
    });

    constructor(
        public service: GestaoPessoasGestaoVdfService,
        public dialog: MatDialog
    ) {}

    ngOnInit() {}

    protected irNovoGrupo() {
        this.dialog.open(GestaoPessoasGestaoVdfComponent, {
            data: { onClose: () => this.service.recarregar() },
        });
    }

    protected irEditarGrupo(linha: { id: number }) {
        this.dialog.open(GestaoPessoasGestaoVdfComponent, {
            data: {
                id: linha.id,
                onClose: () => this.service.recarregar(),
            },
        });
    }

    protected irMenuConfigEditar(linha: { id: number }) {
        this.dialog
            .open(GestaoPessoasGestaoVdfComponent, {
                data: <any>{
                    usuarioGrupoId: linha.id,
                    onClose: () => this.service.recarregar(),
                },
                width: '80%',
                height: '90%',
            })
            .afterClosed()
            .subscribe(() => this.service.recarregar());
    }

    protected irGrupoAtualizarUsuario(linha: { id: number }) {
        this.dialog.open(GestaoPessoasGestaoVdfComponent, {
            data: <any>{
                grupo: linha,
                onClose: () => this.service.recarregar(),
            },
            width: '80%',
            height: '90%',
        });
    }

    displayFn(row: any): string {
        if (row) return `${row?.nome}`;
        else return '';
    }

    situacoes = [
        { valor: 'ATIVO', nome: 'Ativo' },
        { valor: 'INATIVO', nome: 'Inativo' },
    ];
}

