        apiESocialListarOpcoesTabela(
            {keyword: keyword,
            choice_filtro: ChoiceFiltroEnum.ESOCIAL_CLASSIF_EMPLOYEE_BY_POSSESSION})
            .then(response => {
                this.opcoes = response.results.map(item => {return {label: item.titulo, value: item.id}})
            })
