import { apiLimiteDiarias } from 'api/diarias/config/limite-diarias/api-limite-diarias';
import { apiLimiteDiariasEditar } from 'api/diarias/config/limite-diarias/api-limite-diarias-editar.service';
import { MpmtFormularioComponent } from 'components/mpmt-formulario/mpmt-formulario.component';
import moment from 'moment';

class LimiteDiariasEditarComponentData {
    id: number;
    onClose?: Function;
}

@Component({
    selector: 'limite-diarias-editar',
    templateUrl: 'limite-diarias-editar.component.html',
})
export class LimiteDiariasEditarComponent extends MpmtFormularioComponent<LimiteDiariasEditarComponentData> {
    motivos_viagem: any[] = [];

    protected formulario = new FormGroup({
        id: new FormControl<number>(null, [Validators.required]),
        tipo: new FormControl<string>('', [Validators.required]),
        referencia: new FormControl<string>('', [Validators.required]),
        motivos_viagem: new FormControl<number[]>([], [Validators.required]),
        limite: new FormControl<number>(null, [Validators.required]),
        ilimitado: new FormControl<boolean>(false),
        dt_inicio_vigencia: new FormControl<string | null>(null, [Validators.required]),
    }, { validators: this.limiteDiasValidator() });


    ngOnInit() {
        super.ngOnInit();
        this.carregarMotivosViagem();
        this.formulario.get('ilimitado').valueChanges.subscribe((ilimitado) => {
            if (ilimitado) {
                this.formulario.get('limite').disable();
                this.formulario.get('limite').setValue(null);
            } else {
                this.formulario.get('limite').enable();
            }
        });
    }

    constructor(
        @Inject(MAT_DIALOG_DATA)
        protected data: LimiteDiariasEditarComponentData,
        protected dialogRef: MatDialogRef<LimiteDiariasEditarComponentData>,
        protected snackBar: MatSnackBar,
        protected dateAdapter: DateAdapter<Date>,
    ) {
        super(data, snackBar, dialogRef);
        this.dateAdapter.setLocale('pt-BR');
    }

    protected async resetarFormulario() {
        super.resetarFormulario();

        try {
            const { id, tipo, referencia, motivos_viagem, limite, dt_inicio_vigencia } =
                await apiLimiteDiarias({
                    id: this.data.id,
                });

            this.formulario.patchValue({
                id,
                tipo, 
                referencia, 
                motivos_viagem, 
                limite, 
                ilimitado: limite === null,
                dt_inicio_vigencia
            });
        } catch (e) {
            console.log(e);
            this.exibirMensagem(
                'Atenção',
                'Erro inesperado ao carregar os valores do formulário.'
            );
        }
    }

    protected async confirmarFormulario() {
        if (!this.formularioValido) return;

        this.formulario.controls.dt_inicio_vigencia.setValue(moment(this.formulario.controls.dt_inicio_vigencia.value).format('YYYY-MM-DD'))

        const { id, tipo, referencia, motivos_viagem, limite, dt_inicio_vigencia } = this.formulario.value;

        try {
            const {} = await apiLimiteDiariasEditar({
                id,
                tipo, 
                referencia, 
                motivos_viagem, 
                limite: this.formulario.get('ilimitado').value ? null : limite,
                dt_inicio_vigencia
            });

            this.resetarFormulario();
            this.fecharFormulario();
            this.data?.onClose();
        } catch (e: any) {
            const detalheErro = e?.response?.data?.message || '';
            const texto = `Ocorreu um erro inesperado ao salvar o limite. ${detalheErro}`;
            this.exibirMensagem(
                'Atenção',
                texto
            );
        }
    }

    async carregarMotivosViagem() {
        try {
            this.motivos_viagem = (await apiDiariasChoicesMotivosViagem({})).results;
        } catch (error) {
            console.error('Erro ao carregar os motivos de Viagem:', error);
            this.exibirMensagem('Erro', 'Não foi possível carregar os motivos da viagem');
        }
    }

    limiteDiasValidator(): ValidatorFn {
        return (control: AbstractControl): { [key: string]: any } | null => {
            const referenciaControl = control.get('referencia');
            const limiteControl = control.get('limite');

            if (!referenciaControl || !limiteControl) {
                return null;
            }

            const referencia = referenciaControl.value;
            const limite = limiteControl.value;

            if (referencia === 'mensal' && limite > 30) {
                return { 'limiteMensalInvalido': true };
            } else if (referencia === 'anual' && limite > 365) {
                return { 'limiteAnualInvalido': true };
            }

            return null;
        };
    }

    get maxLimite() {
        return this.formulario.controls.referencia.value === 'mensal' ? 30 : 365;
    }

    tipos = [
        { id: 'membro', descricao: 'Membro' },
        { id: 'servidor', descricao: 'Servidor' },
    ];

    referencias = [
        { id: 'anual', descricao: 'Anual' },
        { id: 'mensal', descricao: 'Mensal' },
    ];
}

import { Component, OnInit } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';
import { LimitesDiariasService } from './limites-diarias.service';
import { LimitesDiariasNovoComponent } from './limite-diarias-criar/limite-diarias-novo.component';
import { LimiteDiariasEditarComponent } from './limite-diarias-editar/limite-diarias-editar.component';
import { apiLimiteDiariasApagar } from 'api/diarias/config/limite-diarias/api-limite-diarias-apagar';
import { FuseConfirmationDialogComponent } from '@fuse/services/confirmation/dialog/dialog.component';

@Component({
    selector: 'limites-diarias',
    templateUrl: 'limites-diarias.component.html',
})
export class LimitesDiariasComponent implements OnInit {
    titulo = 'Limites de diárias';

    constructor(
        public service: LimitesDiariasService,
        public dialog: MatDialog,
        private snackBar: MatSnackBar
    ) {}

    ngOnInit() {
        this.configurarColunas();
        this.service.recarregarListagem();
    }

    private configurarColunas() {
        this.service.configurarColunas([
            {
                codigo: 'tipo_display',
                titulo: 'Tipo',
                ordenavel: false,
                visivel: true,
            },
            {
                codigo: 'referencia_display',
                titulo: 'Referência',
                ordenavel: false,
                visivel: true,
            },
            {
                codigo: 'motivos_viagem_display',
                titulo: 'Motivos da viagem',
                ordenavel: false,
                visivel: true,
            },
            {
                codigo: 'limite',
                titulo: 'Limite',
                visivel: true,
                transformarValor: (linha: any) => this.formatarLimite(linha.limite)
            },
            {
                codigo: 'dt_inicio_vigencia',
                titulo: 'Data de início de vigência',
                tipo: 'DATA',
                visivel: true,
            },
            {
                codigo: 'id',
                titulo: 'ID',
                visivel: false,
            },
            {
                codigo: 'criado_por_username',
                titulo: 'Criado por',
                ordenavel: false,
                visivel: false,
            },
            {
                codigo: 'created_at',
                titulo: 'Criado em',
                tipo: 'DATA_HORA',
                visivel: false,
            },
            {
                codigo: 'modificado_por_username',
                titulo: 'Modificado por',
                ordenavel: false,
                visivel: false,
            },
            {
                codigo: 'modified_at',
                titulo: 'Modificado em',
                tipo: 'DATA_HORA',
                visivel: false,
            },
            {
                codigo: 'acoes',
                tipo: 'ACOES',
                ordenavel: false,
                visivel: true,
                acoes: [
                    {
                        icone: 'edit',
                        titulo: 'Editar limite',
                        aoClicar: (linha: any) => this.irEditarLimite(linha),
                    },
                    {
                        titulo: 'Apagar',
                        icone: 'delete',
                        aoClicar: (linha: any) => this.irApagarLimite(linha),
                    },
                ],
            },
        ]);
    }

    protected irNovoLimite() {
        this.dialog.open(LimitesDiariasNovoComponent, {
            data: { onClose: () => this.service.recarregarListagem() },
        });
    }

    protected irEditarLimite(linha: { id: number }) {
        this.dialog.open(LimiteDiariasEditarComponent, {
            data: {
                id: linha.id,
                onClose: () => this.service.recarregarListagem(),
            },
        });
    }


    protected irApagarLimite(linha: { id: number }) {
        const dialogData = {
            title: 'Confirmação de exclusão',
            message: 'Tem certeza que deseja apagar este limite de diárias?',
            icon: { name: 'warning', color: 'warn' },
            actions: {
                cancel: {
                    show: true,
                    label: 'Cancelar'
                },
                confirm: {
                    show: true,
                    label: 'Apagar',
                    useStyle: true,
                    style: {
                        backgroundColor: '#dc2626',
                        color: 'white',
                        border: 'none'
                    }
                }
            }
        };

        const dialogRef = this.dialog.open(FuseConfirmationDialogComponent, {
            width: '400px',
            data: dialogData
        });

        dialogRef.afterClosed().subscribe(result => {
            if (result === 'confirmed') {
                apiLimiteDiariasApagar({ id: linha.id })
                    .then(() => {
                        this.snackBar.open('Limite excluído com sucesso!', '', { duration: 3000 });
                        this.service.recarregarListagem();
                    })
                    .catch(error => {
                        let errorMessage = error?.response?.data?.detail || 'Erro desconhecido ao excluir o limite.';
                        console.error('Erro ao excluir o limite:', error);
                        this.snackBar.open(`Erro ao excluir o limite: ${errorMessage}`, '', { duration: 5000 });
                    });
            }
        });
    }

    private formatarLimite(limite: number | null): string {
        return limite === null ? 'Ilimitado' : `${limite}`;
    }
}

import { Component, Inject, OnInit } from '@angular/core';
import { AbstractControl, FormControl, FormGroup, ValidatorFn, Validators } from '@angular/forms';
import { DateAdapter } from '@angular/material/core';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';
import { apiDiariasChoicesMotivosViagem } from 'api/diarias/choices/api-diarias-motivos-viagem.service';
import { apiLimitesDiariasCriar } from 'api/diarias/config/limite-diarias/api-limite-diarias-criar';
import { MpmtFormularioComponent } from 'components/mpmt-formulario/mpmt-formulario.component';
import moment from 'moment';

class LimitesDiariasNovoComponentData {
    onClose?: Function;
}

@Component({
    selector: 'limite-diarias-novo',
    templateUrl: 'limite-diarias-novo.component.html',
})
export class LimitesDiariasNovoComponent extends MpmtFormularioComponent<LimitesDiariasNovoComponentData> implements OnInit{
    motivos_viagem: any[] = [];

    protected formulario = new FormGroup({
        tipo: new FormControl<string>('', [Validators.required]),
        referencia: new FormControl<string>('', [Validators.required]),
        motivos_viagem: new FormControl<number[]>([], [Validators.required]),
        limite: new FormControl<number>(null, [Validators.required]),
        ilimitado: new FormControl<boolean>(false),
        dt_inicio_vigencia: new FormControl<string | null>(null, [Validators.required]),
    }, { validators: this.limiteDiasValidator() });

    ngOnInit() {
        super.ngOnInit();
        this.carregarMotivosViagem();

        this.formulario.get('ilimitado').valueChanges.subscribe((ilimitado) => {
            if (ilimitado) {
                this.formulario.get('limite').disable();
                this.formulario.get('limite').setValue(null);
            } else {
                this.formulario.get('limite').enable();
            }
        });
    }

    constructor(
        @Inject(MAT_DIALOG_DATA)
        protected data: LimitesDiariasNovoComponentData,
        protected dialogRef: MatDialogRef<LimitesDiariasNovoComponentData>,
        protected snackBar: MatSnackBar,
        protected dateAdapter: DateAdapter<Date>,
    ) {
        super(data, snackBar, dialogRef);
        this.dateAdapter.setLocale('pt-BR');
    }

    protected async confirmarFormulario() {
        if (!this.formularioValido) return;

        this.formulario.controls.dt_inicio_vigencia.setValue(moment(this.formulario.controls.dt_inicio_vigencia.value).format('YYYY-MM-DD'))

        const { tipo, referencia, motivos_viagem, limite, dt_inicio_vigencia } = this.formulario.value;

        try {
            const {} = await apiLimitesDiariasCriar({
                tipo, 
                referencia, 
                motivos_viagem, 
                limite: this.formulario.get('ilimitado').value ? null : limite, 
                dt_inicio_vigencia
            });

            this.resetarFormulario();
            this.fecharFormulario();
            this.data?.onClose();
        } catch (e: any) {
            const detalheErro = e?.response?.data?.message || '';
            const texto = `Ocorreu um erro inesperado ao salvar novo limite. ${detalheErro}`;
            this.exibirMensagem(
                'Atenção',
                texto
            );
        }
    }

    async carregarMotivosViagem() {
        try {
            this.motivos_viagem = (await apiDiariasChoicesMotivosViagem({})).results;
        } catch (error) {
            console.error('Erro ao carregar os motivos de Viagem:', error);
            this.exibirMensagem('Erro', 'Não foi possível carregar os motivos da viagem');
        }
    }

    limiteDiasValidator(): ValidatorFn {
        return (control: AbstractControl): { [key: string]: any } | null => {
            const referenciaControl = control.get('referencia');
            const limiteControl = control.get('limite');

            if (!referenciaControl || !limiteControl) {
                return null;
            }

            const referencia = referenciaControl.value;
            const limite = limiteControl.value;

            if (referencia === 'mensal' && limite > 30) {
                return { 'limiteMensalInvalido': true };
            } else if (referencia === 'anual' && limite > 365) {
                return { 'limiteAnualInvalido': true };
            }

            return null;
        };
    }

    get maxLimite() {
        return this.formulario.controls.referencia.value === 'mensal' ? 30 : 365;
    }

    tipos = [
        { id: 'membro', descricao: 'Membro' },
        { id: 'servidor', descricao: 'Servidor' },
    ];

    referencias = [
        { id: 'anual', descricao: 'Anual' },
        { id: 'mensal', descricao: 'Mensal' },
    ];

}

