import { Component, Inject } from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { MAT_DIALOG_DATA, MatDialog, MatDialogRef } from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';
import { MpmtFormularioComponent } from 'components/mpmt-formulario/mpmt-formulario.component';
import { apiRhDadosBancariosServidorContas } from 'api/rh/api-rh-dados-bancarios-servidor-contas.service';
import { NovaContaComponent } from 'apps/vdf/minhas-diarias/nova-conta/nova-conta.component';
import { apiRhSevidorService } from 'api/rh/api-rh-servidor.service';
import { apiDiariasBeneficiario } from 'api/diarias/api-diarias-beneficiario.service';
import { apiDiariasBeneficiarioEditar } from 'api/diarias/api-diarias-editar-beneficiario.service';

class ManutencaoDadosBancariosComponentData {
    servidor_id: number;
    beneficiario_id: number;
    onClose?: Function;
}

@Component({
    selector: 'manutencao-dados-bancarios',
    templateUrl: 'manutencao-dados-bancarios.component.html',
})
export class ManutencaoDadosBancariosComponent extends MpmtFormularioComponent<ManutencaoDadosBancariosComponentData> {

    lista_contas: any[] =[];
    servidor: any = null;

    protected formulario = new FormGroup({
        conta: new FormControl<number[]>(null, [Validators.required]),

    });

    constructor(
        @Inject(MAT_DIALOG_DATA)
        protected data: ManutencaoDadosBancariosComponentData,
        protected dialogRef: MatDialogRef<ManutencaoDadosBancariosComponentData>,
        protected snackBar: MatSnackBar,
        public dialog: MatDialog,

    ) {
        super(data, snackBar, dialogRef);
    }

    ngOnInit() {
        this.carregarDadosServidor();
        this.carregarContas();
        this.carregarDados();

    }

    async carregarDados() {
        if (this.data.beneficiario_id != null) {
            const results = await apiDiariasBeneficiario({
                id: this.data.beneficiario_id
            });
            this.formulario.get('conta')?.setValue([results.conta_bancaria_pgto]);
        }

    }



    protected async confirmarFormulario() {
        if (!this.formularioValido) return;

        const { conta } = this.formulario.value;

        if (this.data.beneficiario_id != null) {
            try {

                const { } = await apiDiariasBeneficiarioEditar
                    ({
                        id: this.data.beneficiario_id,
                        conta_bancaria_pgto: conta[0]
                    });

                this.exibirMensagem('', 'Beneficiário atualizado com sucesso.','sucess-snackbar')
                this.fecharFormulario();
                this.data?.onClose();

            } catch (e: any) {
                console.error(e)
                const detalheErro = e?.response?.data?.message || '';
                const texto = `Ocorreu um erro inesperado ao salvar rascunho. ${detalheErro}`;
                this.exibirMensagem('Aviso', texto);
            }
        }else{

            this.dialogRef.close({
                conta: conta[0]
                });
        }
    }

    public async carregarContas() {
        try {
            this.lista_contas = (await apiRhDadosBancariosServidorContas({servidor_id:this.data.servidor_id})).results;
        } catch (error) {
            console.error('Erro ao carregar as contas do servidor:', error);
        }
    }

    public async carregarDadosServidor() {
        try {
            this.servidor = (await apiRhSevidorService({id:this.data.servidor_id}));
        } catch (error) {
            console.error('Erro ao carregar dados do servidor:', error);
        }
    }

    protected irAdicionarNovaConta() {

        const d_conta =  this.dialog.open(NovaContaComponent, {
            data: { servidor_id: this.data.servidor_id },
        });


        d_conta.afterClosed().subscribe(result => {
            if (result) {    
                this.formulario.get('conta')?.setValue([result.conta]);
                this.carregarContas();
            }
        });
    }
}

import {
    ChangeDetectionStrategy,
    ChangeDetectorRef,
    Component,
    OnDestroy,
    OnInit,
    TemplateRef,
    ViewChild,
    ViewContainerRef,
    ViewEncapsulation,
} from '@angular/core';
import { Overlay, OverlayRef } from '@angular/cdk/overlay';
import { TemplatePortal } from '@angular/cdk/portal';
import { MatButton } from '@angular/material/button';
import { Subject, takeUntil } from 'rxjs';
import { Message } from 'layout/common/messages/messages.types';
import { MessagesService } from 'layout/common/messages/messages.service';

@Component({
    selector: 'messages',
    templateUrl: './messages.component.html',
    encapsulation: ViewEncapsulation.None,
    changeDetection: ChangeDetectionStrategy.OnPush,
    exportAs: 'messages',
})
export class MessagesComponent implements OnInit, OnDestroy {
    @ViewChild('messagesOrigin') private _messagesOrigin: MatButton;
    @ViewChild('messagesPanel') private _messagesPanel: TemplateRef<any>;

    messages: Message[];
    unreadCount: number = 0;
    private _overlayRef: OverlayRef;
    private _unsubscribeAll: Subject<any> = new Subject<any>();

    /**
     * Constructor
     */
    constructor(
        private _changeDetectorRef: ChangeDetectorRef,
        private _messagesService: MessagesService,
        private _overlay: Overlay,
        private _viewContainerRef: ViewContainerRef
    ) {}

    // -----------------------------------------------------------------------------------------------------
    // @ Lifecycle hooks
    // -----------------------------------------------------------------------------------------------------

    /**
     * On init
     */
    ngOnInit(): void {
        // Subscribe to message changes
        this._messagesService.messages$
            .pipe(takeUntil(this._unsubscribeAll))
            .subscribe((messages: Message[]) => {
                // Load the messages
                this.messages = messages;

                // Calculate the unread count
                this._calculateUnreadCount();

                // Mark for check
                this._changeDetectorRef.markForCheck();
            });
    }

    /**
     * On destroy
     */
    ngOnDestroy(): void {
        // Unsubscribe from all subscriptions
        this._unsubscribeAll.next(null);
        this._unsubscribeAll.complete();

        // Dispose the overlay
        if (this._overlayRef) {
            this._overlayRef.dispose();
        }
    }

    // -----------------------------------------------------------------------------------------------------
    // @ Public methods
    // -----------------------------------------------------------------------------------------------------

    /**
     * Open the messages panel
     */
    openPanel(): void {
        // Return if the messages panel or its origin is not defined
        if (!this._messagesPanel || !this._messagesOrigin) {
            return;
        }

        // Create the overlay if it doesn't exist
        if (!this._overlayRef) {
            this._createOverlay();
        }

        // Attach the portal to the overlay
        this._overlayRef.attach(
            new TemplatePortal(this._messagesPanel, this._viewContainerRef)
        );
    }

    /**
     * Close the messages panel
     */
    closePanel(): void {
        this._overlayRef.detach();
    }

    /**
     * Mark all messages as read
     */
    markAllAsRead(): void {
        // Mark all as read
        this._messagesService.markAllAsRead().subscribe();
    }

    /**
     * Toggle read status of the given message
     */
    toggleRead(message: Message): void {
        // Toggle the read status
        message.read = !message.read;

        // Update the message
        this._messagesService.update(message.id, message).subscribe();
    }

    /**
     * Delete the given message
     */
    delete(message: Message): void {
        // Delete the message
        this._messagesService.delete(message.id).subscribe();
    }

    /**
     * Track by function for ngFor loops
     *
     * @param index
     * @param item
     */
    trackByFn(index: number, item: any): any {
        return item.id || index;
    }

    // -----------------------------------------------------------------------------------------------------
    // @ Private methods
    // -----------------------------------------------------------------------------------------------------

    /**
     * Create the overlay
     */
    private _createOverlay(): void {
        // Create the overlay
        this._overlayRef = this._overlay.create({
            hasBackdrop: true,
            backdropClass: 'fuse-backdrop-on-mobile',
            scrollStrategy: this._overlay.scrollStrategies.block(),
            positionStrategy: this._overlay
                .position()
                .flexibleConnectedTo(
                    this._messagesOrigin._elementRef.nativeElement
                )
                .withLockedPosition(true)
                .withPush(true)
                .withPositions([
                    {
                        originX: 'start',
                        originY: 'bottom',
                        overlayX: 'start',
                        overlayY: 'top',
                    },
                    {
                        originX: 'start',
                        originY: 'top',
                        overlayX: 'start',
                        overlayY: 'bottom',
                    },
                    {
                        originX: 'end',
                        originY: 'bottom',
                        overlayX: 'end',
                        overlayY: 'top',
                    },
                    {
                        originX: 'end',
                        originY: 'top',
                        overlayX: 'end',
                        overlayY: 'bottom',
                    },
                ]),
        });

        // Detach the overlay from the portal on backdrop click
        this._overlayRef.backdropClick().subscribe(() => {
            this._overlayRef.detach();
        });
    }

    /**
     * Calculate the unread count
     *
     * @private
     */
    private _calculateUnreadCount(): void {
        let count = 0;

        if (this.messages && this.messages.length) {
            count = this.messages.filter((message) => !message.read).length;
        }

        this.unreadCount = count;
    }
}

import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import { printDate } from 'utils/print-date';
import { MatPaginator } from '@angular/material/paginator';
import { tap } from 'rxjs';
import { RhPvfMinhasAnotacoesDataSource } from 'datasources/rh-pvf-minhas-anotacoes.datasource';
import { MinhasAnotacoesShow } from './minhas-anotacoes-show/minhas-anotacoes-show.component';
import { apiReportRhPvfAnotacaoPessoalService } from 'api/report/api-report-rh-pvf-anotacao-pessoal.service';
import { useDownload } from 'api/@base/use-download';
import { apiRhPvfTiposAnotacao } from 'api/rh/api-rh-pvf-tipos-anotacoes.service';
import { Payload } from 'api/report/api-report-rh-pvf-anotacao-pessoal.service';

@Component({
    selector: 'app-minhas-anotacoes',
    templateUrl: './minhas-anotacoes.component.html',
})
export class MinhasAnotacoesComponent implements OnInit {
    @ViewChild(MatPaginator) paginator: MatPaginator;

    printDate = printDate;

    dataSource = new RhPvfMinhasAnotacoesDataSource();

    tiposAnotacao: { label: string; value: string }[] = [];
    filters: {
        keyword: string | undefined;
        tipo_anotacao_id: number[] | undefined;
    } = { keyword: undefined, tipo_anotacao_id: [] };

    displayedColumns: string[] = [
        'tipo_label',
        'documento_tipo_label',
        'publicacao_label',
        'documento_numero',
        'documento_data',
        'gedoc_numero',
        'anotacao',
    ];

    constructor(public dialog: MatDialog) {}

    ngOnInit() {
        this.loadTiposAnotacao();
        this.load();
    }

    public async load() {
        await this.dataSource.load({
            page: 1,
            per_page: 10,
        });
    }

    private async loadTiposAnotacao() {
        const { results } = await apiRhPvfTiposAnotacao({});
        this.tiposAnotacao = results;
    }

    applyFilter() {
        this.dataSource.load({
            ...this.filters,
            tipo_anotacao_id: this.filters.tipo_anotacao_id.join(','),
            page: (this.paginator.pageIndex || 0) + 1,
            per_page: this.paginator.pageSize,
        });
    }

    ngAfterViewInit() {
        this.paginator.page.pipe(tap(() => this.applyFilter())).subscribe();
    }

    public showAnotacao(element: any) {
        const dialogRef = this.dialog.open(MinhasAnotacoesShow, {
            width: '99%',
            maxHeight: '90vh',
            data: { element },
        });

        dialogRef.afterClosed().subscribe((result) => {});
    }

    isLoading: boolean = false;

    async download() {
        try {
            this.isLoading = true;

            let payload: Payload = {};

            if (
                this.filters.tipo_anotacao_id &&
                this.filters.tipo_anotacao_id.length > 0
            ) {
                payload.tipos_anotacao = this.filters.tipo_anotacao_id;
            }

            const { message, uuid, success } =
                await apiReportRhPvfAnotacaoPessoalService(payload);

            if (!success) return;

            await useDownload(uuid);
        } finally {
            this.isLoading = false;
        }
    }
}

