                }
                this.service.recarregarListagem();
            });
            this.service.recarregarListagem();
            this.service.carregarSituacoes();
            this.service.carregarMotivosViagem();
            this.service.carregarFinalidades();
        }).catch(error => {
            console.error('Erro ao carregar o usuário atual:', error);
