                visivel: true,
            },
            {
                codigo: 'importada',
                titulo: 'Viagem importada',
                tipo: 'BOLEANO',
                ordenavel: false,
                visivel: true,
            },
            {
                codigo: 'possui_excedente',
                titulo: 'Possui excedente',
                tipo: 'BOLEANO',
                ordenavel: false,
                visivel: true,
            },
            {
                codigo: 'excedente',
                titulo: 'Viagem excedente',
                tipo: 'BOLEANO',
                ordenavel: false,
                visivel: true,
            },
            {
                codigo: 'motorista',
                titulo: 'Viagem de motorista',
                tipo: 'BOLEANO',
                ordenavel: false,
                visivel: true,
            },
            {
                codigo: 'hospedagem_anfitriao',
                titulo: 'Hospedagem anfitrião',
                tipo: 'BOLEANO',
                ordenavel: false,
                visivel: false,
            },
            {
                codigo: 'finalidade_viagem_display',
                titulo: 'Finalidade',
                ordenavel: false,
                visivel: false,
            },
            {
                codigo: 'motivo_viagem_display',
                titulo: 'Motivo',
                ordenavel: false,
                visivel: false,
            },
            {
                codigo: 'tipo_viagem_display',
                titulo: 'Tipo',
