import {
    Component,
    Input,
    OnChanges,
    OnInit,
    SimpleChanges,
    ViewChild,
} from '@angular/core';
import { FormGroup } from '@angular/forms';
import { MatPaginator } from '@angular/material/paginator';
import { BehaviorSubject, Observable, map, switchMap, tap } from 'rxjs';
import { pvfRequestsService } from 'services/pvf-requests.service';

@Component({
    selector: 'mpmt-listagem',
    templateUrl: './mpmt-listagem.component.html',
})
export class MpmtListagemComponent implements OnInit, OnChanges {
    @ViewChild(MatPaginator) paginator: MatPaginator;

    public filtros: FormGroup = new FormGroup({});

    private colunasSubject = new BehaviorSubject<{ [key: string]: string }>({});
    private listagemSubject = new BehaviorSubject<any[]>([]);
    private loadingSubject = new BehaviorSubject<boolean>(false);
    private totalSubject = new BehaviorSubject<number>(0);
    private perPageSubject = new BehaviorSubject<number>(10);

    public colunas$ = this.colunasSubject.asObservable();
    public colunaTitulos$ = this.colunasSubject.asObservable();
    public listagem$ = this.listagemSubject.asObservable();
    public loading$ = this.loadingSubject.asObservable();
    public total$ = this.totalSubject.asObservable();
    public perPage$ = this.perPageSubject.asObservable();

    constructor() {}

    ngOnInit() {
        this.configurarColunas();
        this.configurarDados();
    }

    ngAfterViewInit() {
        if (this.paginator)
            this.paginator.page
                .pipe(tap(() => this.configurarDados()))
                .subscribe();
    }

    ngOnChanges(changes: SimpleChanges) {
        this.aplicarFiltros();
    }

    protected async configurarColunas() {
        this.colunasSubject.next(await this.obterColunas());
    }

    protected async configurarDados() {
        const filtros = await this.obterFiltros();
        const response = await this.obterDados(filtros);

        this.listagemSubject.next(response.results);
        this.totalSubject.next(response.total);
        this.perPageSubject.next(response.per_page);
    }

    protected async aplicarFiltros() {
        this.loadingSubject.next(true);
        await this.configurarDados();
        this.loadingSubject.next(false);
    }

    protected async obterColunas(): Promise<{ [key: string]: string }> {
        return {};
    }

    protected obterTitulo() {
        return 'Listagem';
    }

    protected async obterDados(filtros: any): Promise<{
        total?: number;
        page?: number;
        per_page?: number;
        results: any[];
    }> {
        const response = await pvfRequestsService(filtros);
        return response;
    }

    protected async obterFiltros(): Promise<{ [key: string]: any }> {
        return {
            page: (this.paginator?.pageIndex || 0) + 1,
            per_page: this.paginator?.pageSize || 10,
        };
    }

    protected alterarOrdenacao($event: {
        active: string;
        direction: 'asc' | 'desc';
    }) {
        const { active, direction } = $event;
        this.filtros.patchValue({
            order_by: direction == 'asc' ? active : `-${active}`,
        });
        this.aplicarFiltros();
    }

    protected get colunasVisiveis() {
        return this.colunas$.pipe(map((value) => Object.keys(value)));
    }

    protected get colunasVisiveisComAcao() {
        return this.colunasVisiveis.pipe(
            map((x) => {
                return [...x, 'acao'];
            })
        );
    }
}

import { Component, Input } from '@angular/core';
import { CdkDragDrop, moveItemInArray } from '@angular/cdk/drag-drop';

import { MpmtListagem2Coluna, MpmtListagem2Linha } from 'components/mpmt-listagem2/mpmt-listagem2.interface';
import { MpmtListagem2Component } from 'components/mpmt-listagem2/mpmt-listagem2.component';
import { BehaviorSubject, Subject, take, takeUntil } from 'rxjs';
import moment from 'moment';
import { MpmtListagemReordenavelService } from './mpmt-listagem-reordenavel.service';

@Component({
    selector: 'mpmt-listagem-reordenavel',
    templateUrl: './mpmt-listagem-reordenavel.component.html',
})
export class MpmtListagemReordenavelComponent extends MpmtListagem2Component {
    @Input('service') service: MpmtListagemReordenavelService;

    dragAtivo = false;
    localData: MpmtListagem2Linha[] = [];
    backupData: MpmtListagem2Linha[];
    private destroy$ = new Subject<void>();

    ngOnInit() {
        super.ngOnInit();
        this.service.listagem$.pipe(takeUntil(this.destroy$)).subscribe(dados => {
            this.localData = dados;
        });
    }

    ngOnDestroy() {
        this.destroy$.next();
        this.destroy$.complete();
    }

    atualizarListagem() {
        this.service.paginacao.page = this.paginator.pageIndex + 1;
        this.service.paginacao.per_page = this.paginator.pageSize;
        this.service.recarregarListagem();
    }

    ativarDragMode() {
        this.dragAtivo = !this.dragAtivo;
        if (this.dragAtivo) {
            this.backupData = [...this.localData];
            this.renumerarOrdem();
            this.service.total$.pipe(
                take(1)
            ).subscribe(total => {
                this.paginator.pageSize = total;
                this.paginator.pageIndex = 0;
                this.atualizarListagem();
            });
        } else {
            this.paginator.pageSize = 10;
            this.atualizarListagem();
        }
    }

    renumerarOrdem() {
        this.localData.forEach((item, index) => {
            item.ordem = index + 1;
        });
        this.localData = [...this.localData];
    }

    drop(event: CdkDragDrop<any[]>) {
        const previousIndex = event.previousIndex;
        const currentIndex = event.currentIndex;

        if (previousIndex !== currentIndex) {
            moveItemInArray(this.localData, previousIndex, currentIndex);
            this.localData = [...this.localData];
            this.renumerarOrdem();
        }
    }

    cancelarEdicao() {
        this.dragAtivo = false;
        this.localData = this.backupData;
        this.backupData = [];
        this.service.recarregarListagem();
    }

    salvarOrdem() {
        this.service.atualizarOrdem(this.localData)
        .then(() => {
            this.dragAtivo = false;
            this.service.recarregarListagem();
        })
        .catch(error => {
            console.error("Erro ao salvar a ordem:", error);
        });
    }


    @Input('coluna') coluna: MpmtListagem2Coluna;
    @Input('linha') linha: MpmtListagem2Linha;

    private valorSubject = new BehaviorSubject<
        string | number | boolean | Date
    >(undefined);
    public valor$ = this.valorSubject.asObservable();

    ngOnChanges() {
        if (!this.coluna) return;
        if (!this.linha) return;

        this.valorSubject.next(this.contruirValor(this.coluna, this.linha));
    }

    contruirValor(coluna: MpmtListagem2Coluna, linha: MpmtListagem2Linha) {
        if (!coluna) return;
        if (!linha) return;
        const valor = this.linha[this.coluna.codigo];
        if (!this.coluna.transformarValor) return valor;
        return this.coluna.transformarValor(valor);
    }

    formatarData = (data) => moment(data).format('DD/MM/YYYY');
    formatarDataHora = (data) => moment(data).format('DD/MM/YYYY HH:MM');
    formatarBooleano = (valor: boolean) => valor ? 'Sim' : 'Não';
}

import { Component, Input, OnInit, ViewChild } from '@angular/core';
