    displayFn(row: any): string {
        if (row) return `${row?.nome}`;
        else return '';
    }

    async deleteItem(row: any) {
        try {
            await apiPainelControleControleAcessoMenuConfigApagar({
                id: row.id,
            });
            this.configurarDados();
        } catch (e) {
            console.error(e);
        }
    }

    situacoes = [
        { valor: 'ATIVO', nome: 'Ativo' },
        { valor: 'INATIVO', nome: 'Inativo' },
    ];
}

