    get statusGroup() {
        if (
            this.data?.status ==
            RequestStatusEnum.AGUARDANDO_CIENCIA_DO_SUBSTITUTO
        )
            return 'PROGRESS';
        if (this.data?.status == RequestStatusEnum.AGUARDANDO_APROVADOR)
