                            (results) =>
                                (this.listaTipoDependente = results.filter(
                                    (result) =>
                                        result['value'] ==
                                            TipoDependenteIrEnum.ENTEADO_ABSOLUTAMENTE_INCAPAZ ||
                                        result['value'] ==
