@Component({
    selector: 'vdf-folha-ponto-justificativas',
    templateUrl: 'vdf-folha-ponto-justificativas.component.html',
    encapsulation: ViewEncapsulation.None,
})
export class VdfFolhaPontoJustificativasComponent implements OnInit {
    constructor(
        @Inject(MAT_DIALOG_DATA)
        protected data: VdfFolhaPontoJustificativasComponentData,
        public service: VdfFolhaPontoJustificativasService,
        private _fuseConfirmationService: FuseConfirmationService,
        protected dialogRef: MatDialogRef<VdfFolhaPontoJustificativasComponentData>,
        protected snackBar: MatSnackBar,
        public dialog: MatDialog,
        private currentUserService: CurrentUserService
    ) {
        const filtros = data?.filtros;

        if (filtros) {
            this.service.filtros.reset();
            this.service.filtros.patchValue({
                ...filtros,
                servidor_id:
                    filtros.servidor_id ||
                    this.currentUserService.currentUser.id,
            });
        }
    }

    modalButtons: ModalButton[] = [
        {
            label: 'Incluir Justificativa',
            action: () => this.irNovo(),
            color: 'white',
            backgroundColor: CoresPadraoEnum.azul
        }
    ];

    ngOnInit() {
        this.configurarColunas();
        this.service.recarregarListagem();
    }

    private configurarColunas() {
        this.service.configurarColunas([
            {
                titulo: 'Motivo',
                codigo: 'tipo_justificativa_display',
                visivel: true,
            },
            {
                titulo: 'Data Inicio',
                codigo: 'data_inicio',
                visivel: true,
                tipo: 'DATA',
            },
            {
                titulo: 'Data fim',
                codigo: 'data_fim',
                visivel: true,
                tipo: 'DATA',
            },
            {
                titulo: 'Qtd. Horas',
                codigo: 'horas',
                visivel: true,
            },
            {
                titulo: 'Observações',
                codigo: 'observacao',
                visivel: true,
            },
            {
                titulo: 'Baixar',
                codigo: 'baixar',
                tipo: 'ICONE',
                transformarValor: () => 'heroicons_solid:paper-clip',
                aoClicar: (item: any) => this.download(item),
                visivel: true,
                exibirSe: (row) => row.anexo_id,
                construirEstilo: () => 'cursor-pointer',
            },
            {
                codigo: 'acoes',
                tipo: 'ACOES',
                ordenavel: false,
                visivel: true,
                acoes: [
                    {
                        icone: 'delete',
                        titulo: 'Excluir',
                        aoClicar: (linha: any) => this.irExcluir(linha),
                    },
                ],
            },
        ]);
    }

    async download(item) {
        try {
            await useGedDownload(item.anexo_id);
        } finally {
        }
    }

    async irExcluir(item) {
        const dialogRef = this._fuseConfirmationService.open({
            title: 'Confirmação',
            message: 'Você tem certeza que deseja excluir essa justificativa?',
            icon: {
                show: true,
                name: 'heroicons_outline:exclamation',
                color: 'warn'
            },
            actions: {
                confirm: {
                    show: true,
                    label: 'Excluir',
                    style: { 'background-color': '#dc2626' },
                },
                cancel: {
                    show: true,
                    label: 'Cancelar',
                    style: { 'background-color': '#cbd5e1' },
                    useClass: true,
                    class: 'text-black'
                }
            },
            dismissible: true
        });

        dialogRef.afterClosed().subscribe(async (result) => {
            if (result === 'confirmed') {
                try {
                    const response = await apiFolhaPontoJustificativaCancelar({
                        justificativa_id: item.id,
                    });

                    this.exibirMensagem('', 'Justificativa excluída com sucesso.');

                    this.service.recarregarListagem();
                } catch (e: any) {
                    const detalheErro = e?.response?.data?.error || e?.response?.data?.datail || 'Erro ao excluir justificativa.';
                    this.exibirMensagem(
                        'Atenção',
                        detalheErro
                    );
                }
            }
        });
    }


    public irNovo() {
        const dialogRef = this.dialog.open(
            VdfFolhaPontoJustificativaNovoComponent,
            {
                data: {
                    ...this.data?.filtros,
                    close: () => {
                        dialogRef.close();
                    },
                },
            }
        );

        dialogRef.afterClosed().subscribe((result) => {
            this.service.recarregarListagem();
        });
    }

    printDate(d) {
        return moment(d).format('DD/MM/YYYY');
    }

    protected exibirMensagem(titulo: string, texto: string, classe: string = 'custom-snackbar') {
        this.snackBar.open(texto, '', {
            duration: 4000,
            horizontalPosition: 'center',
            verticalPosition: 'top',
            panelClass: [classe],
        });
    }

    protected fecharFormulario() {
        this.dialogRef.close();
    }
}

import { Component, Inject } from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { DateAdapter } from '@angular/material/core';
import {
    MAT_DIALOG_DATA,
    MatDialog,
    MatDialogRef,
} from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';
import { apiFolhaPontoIgnorarBatida } from 'api/folha-ponto/api-folha-ponto-ignorar-batida.service';
import { ApiFolhaPontoMarcacoesItem } from 'api/folha-ponto/api-folha-ponto-marcacoes.service';
import { MpmtFormularioComponent } from 'components/mpmt-formulario/mpmt-formulario.component';

class VdfFolhaPontoMarcacaoEditarComponentData {
    onClose?: Function;
    marcacao?: ApiFolhaPontoMarcacoesItem;
}

@Component({
    selector: 'vdf-folha-ponto-marcacao-editar',
    templateUrl: 'vdf-folha-ponto-marcacao-editar.component.html',
})
export class VdfFolhaPontoMarcacaoEditarComponent extends MpmtFormularioComponent<VdfFolhaPontoMarcacaoEditarComponentData> {
    protected formulario = new FormGroup({
        selecionados: new FormControl<string[]>([], []),
    });

    constructor(
        @Inject(MAT_DIALOG_DATA)
        protected data: VdfFolhaPontoMarcacaoEditarComponentData,
        protected dialogRef: MatDialogRef<VdfFolhaPontoMarcacaoEditarComponentData>,
        protected snackBar: MatSnackBar,
        protected dateAdapter: DateAdapter<Date>,
        public dialog: MatDialog
    ) {
        super(data, snackBar, dialogRef);
        this.dateAdapter.setLocale('pt-BR');
    }

    get formularioEhValido() {
        return this.formulario?.value?.selecionados?.length > 0;
    }

    protected async confirmarFormulario() {
        if (!this.formularioValido) return;

        const { selecionados } = this.formulario.value;

        try {
            for await (const marcacao_id of selecionados) {
                const {} = await apiFolhaPontoIgnorarBatida({
                    marcacao_id,
                });
            }

            this.resetarFormulario();
            this.fecharFormulario();
            if(this.data?.onClose)this.data?.onClose();
        } catch (e: any) {
            console.log(e);
            const detalheErro =
                e?.response?.data?.resposta ||
                'Ocorreu um erro inesperado ao salvar o valor.';
            const texto = `${detalheErro}`;
            this.exibirMensagem('Atenção', texto);
        }
    }

    ehSelecionado(marcacao) {
        return this.formulario.value.selecionados.includes(marcacao.id);
    }

    mudarSelecionado($event, marcacao) {
        if ($event?.checked) {
            this.formulario.patchValue({
                selecionados: [],
            });
            this.formulario.value.selecionados.push(marcacao.id);
        } else {
            this.formulario.patchValue({
                selecionados: this.formulario.value.selecionados.filter(
                    (id) => id != marcacao.id
                ),
            });
        }
    }
}

