async <M extends object | [] = any>(
    target: string,
    payload: any = {},
    headers: any = {}
): Promise<AxiosBaseResponse<M>> => {
    return await axios
        .delete(url(target), {
            headers: { ...headers, remote: environment.remote },
            params: payload,
        })
        .catch((error) => {
            throw new AxiosBaseResponse<M>(error);
        })
        .then((response) => {
            return new AxiosBaseResponse<M>(response);
        });
}

async <M extends object | [] = any>(
    target: string,
    payload: any = {},
    headers: any = {},
    responseType: ResponseType = undefined
): Promise<AxiosBaseResponse<M>> => {
    return await axios
        .get(url(target), {
            headers: { ...headers, remote: environment.remote },
            params: payload,
            data: payload,
            responseType: responseType,
        })
        .catch((error) => {
            throw new AxiosBaseResponse<M>(error?.response || error);
        })
        .then((response) => {
            return new AxiosBaseResponse<M>(response);
        });
}

async <M extends object | [] = any>(
    target: string,
    params: any,
    headers: any = undefined
): Promise<AxiosBaseResponse<M>> => {
    return await axios
        .post(url(target), params, {
            headers: { ...headers, remote: environment.remote },
        })
        .catch((error) => {
            // console.log('error', error);
            throw error;
            // new AxiosBaseResponse<M>(error);
        })
        .then((response) => {
            return new AxiosBaseResponse<M>(response);
        });
}

async <M extends object | [] = any>(
    target: string,
    payload: any = {},
    headers: any = {}
): Promise<AxiosBaseResponse<M>> => {
    return await axios
        .put(url(target), payload, {
            headers: { ...headers, remote: environment.remote },
        })
        .catch((error) => {
            throw error;
        })
        .then((response) => {
            return new AxiosBaseResponse<M>(response);
        });
}

