src/utils/add-day.ts.defaultValue:
(date: Date, n: number): Date => {
    // console.log('date', date, date instanceof moment, typeof date);
    if (date instanceof moment) {
        let a = moment(date);
        a = a.add(n, 'days');
        return a.toDate();
    } else {
        const d = new Date();
        d.setTime(date.getTime() + n * 24 * 60 * 60 * 1000);
        return d;
    }
}

src/utils/add-minute.ts.defaultValue:
(date: Date, n: number): Date => {
    const d = new Date();
    d.setTime(d.getTime() + n * 60 * 1000);
    return d;
}

