src/api/@base/use-delete.ts.defaultValue:
async <M extends object | [] = any>(
    target: string,
    payload: any = {},
    headers: any = {}
): Promise<AxiosBaseResponse<M>> => {
    return await axios
        .delete(url(target), {
            headers: { ...headers, remote: environment.remote },
            params: payload,
        })
        .catch((error) => {
            throw new AxiosBaseResponse<M>(error);
        })
        .then((response) => {
            return new AxiosBaseResponse<M>(response);
        });
}

src/api/@base/use-get.ts.defaultValue:
async <M extends object | [] = any>(
    target: string,
    payload: any = {},
    headers: any = {},
    responseType: ResponseType = undefined
): Promise<AxiosBaseResponse<M>> => {
    return await axios
        .get(url(target), {
            headers: { ...headers, remote: environment.remote },
            params: payload,
            data: payload,
            responseType: responseType,
        })
        .catch((error) => {
            throw new AxiosBaseResponse<M>(error?.response || error);
        })
        .then((response) => {
            return new AxiosBaseResponse<M>(response);
        });
}

